import { useState } from 'react'
import { injectIntl, FormattedMessage } from 'react-intl'
import moment from 'moment'
import Select from '../SelectV2'

import {
  FlexContainer,
  DisclaimerText
} from '../DatePicker/DatePicker.style'

function TimePicker (props) {
  const { intl, name, handleTimeChange, value, disabled, error } = props

  const { formatMessage } = intl

  const [hour, setHour] = useState(value ? moment(value, 'HH:mm').hour() : undefined)
  const [minute, setMinute] = useState(value ? moment(value, 'HH:mm').minute() : undefined)

  const hourOptions = new Array(24).fill(undefined).map((_, index) => ({
    id: index,
    value: index,
    displayName: String(index)
  }))

  const minuteOptions = new Array(60).fill(undefined).map((_, index) => ({
    id: index,
    value: index,
    displayName: String(index)
  }))

  const changeTime = ({ hour, minute }) => {
    if (hour !== undefined && minute !== undefined) {
      let newHourValue = hour
      let newMinuteValue = minute
      if (minute < 10) {
        newMinuteValue = `0${minute}`
      }
      if (newHourValue < 10) {
        newHourValue = `0${hour}`
      }
      handleTimeChange(`${newHourValue}:${newMinuteValue}`, name)
    }
  }

  return (
    <>
      <FlexContainer>
        <Select
          value={hour}
          error={error}
          disabled={disabled}
          options={hourOptions}
          placeholder={formatMessage({
            id: 'Jam',
            defaultMessage: 'Jam'
          })}
          onSelect={(value) => {
            changeTime({ hour: value, minute })
            setHour(value)
          }}
        />

        <Select
          value={minute}
          error={error}
          disabled={disabled}
          options={minuteOptions}
          placeholder={formatMessage({
            id: 'Menit',
            defaultMessage: 'Menit'
          })}
          onSelect={(value) => {
            changeTime({ hour, minute: value })
            setMinute(value)
          }}
        />
      </FlexContainer>
      <DisclaimerText>
        <FormattedMessage
          id='Anda tidak perlu menentukan secara tepat waktu kejadian, cukup waktu yang paling mendekati.'
          defaultMessage='Anda tidak perlu menentukan secara tepat waktu kejadian, cukup waktu yang paling mendekati.'
        />
      </DisclaimerText>
    </>
  )
}

export default injectIntl(TimePicker)
