import { useMutation } from '@tanstack/react-query'
import axios from 'axios'
import request from '../../axios/claim'

export const useFileUploadMutation = (options) => {
  return useMutation({
    mutationFn: async ({ file, name, claimId, formName, timestamp }) => {
      const formData = new FormData()
      formData.append('file', file, file.name)
      formData.append('attribute', [name])

      const signedRes = await request.getSignedUrl({ formData })
      if (signedRes.status !== 200) throw new Error(signedRes?.data?.message)
      const signedUrlData = signedRes.data

      await axios.put(signedUrlData.signed_url, file, {
        headers: { 'Content-Type': file.type, 'Host': 'storage.googleapis.com' },
      })

      const attrFormData = new FormData()
      attrFormData.append('attribute', [name])
      if (timestamp) {
        attrFormData.append('timestamp_date', timestamp.timestamp_date)
        attrFormData.append('timestamp_time', timestamp.timestamp_time)
        attrFormData.append('timestamp_utc_offset', timestamp.timestamp_utc_offset)
      }
      await request.uploadGenericClaimDoc({
        claim_id: claimId,
        form: formName,
        formData: attrFormData,
        signedUrlData,
      })

      return { url: signedUrlData.url, filename: signedUrlData.filename }
    },
    networkMode: 'always',
    ...options,
  })
}
