import { useHistory } from 'react-router'
import { STATUS_GROUP_DOC_RECEIVED, STATUS_GROUP_INITIATED } from '../../../constants'
import { LANG_STRINGS } from '../../../constants/lang'
import { ArrowRight, CheckLine } from '../../../image'
import { Right, StatusText, Title, UserDetailWrapper, UserList, UserName, Wrapper } from './claimFamilyDetails.style'
import { FormattedMessage } from 'react-intl'

const statusToText = {
  [STATUS_GROUP_INITIATED]: LANG_STRINGS.completeClaimForm,
  [STATUS_GROUP_DOC_RECEIVED]: LANG_STRINGS.CompletedClaimForm
}

function ClaimFamilyDetails ({ userList = [] }) {
  const history = useHistory()
  if (!userList.length) return null
  const goToClaimId = (id) => {
    history.push(`/claimdetail/${id}`)
  }
  return (
    <Wrapper>
      <Title>
        <FormattedMessage id={LANG_STRINGS.claimMustBeResolved} />
      </Title>
      <UserList>
        {
        userList?.map((userDetail) => {
          const {
            claim_id: claimId,
            user_name: userName,
            status_group: status
          } = userDetail
          return (
            <UserDetailWrapper status={status} onClick={() => goToClaimId(claimId)}>
              <Right>
                <UserName>
                  {userName}
                </UserName>
                <StatusText>
                  <FormattedMessage id={statusToText[status]} />
                </StatusText>
              </Right>
              <div>
                {
                  STATUS_GROUP_INITIATED === status
                    ? <img src={ArrowRight} />
                    : <img src={CheckLine} />
                }
              </div>
            </UserDetailWrapper>
          )
        })
        }
      </UserList>
    </Wrapper>
  )
}

export default ClaimFamilyDetails
