import AddressForm from './AddressForm'
import ViewServiceCenterForm from './ViewServiceCenterForm'

function ClaimServiceCenterForm ({
  claimId,
  serviceCenterForm = {}
}) {
  const { is_valid: isValid, attributes, name } = serviceCenterForm
  return (
    isValid
      ? <ViewServiceCenterForm
        claimId={claimId}
        serviceCenterForm={serviceCenterForm}
      />
      : <AddressForm
        formName={name}
        attributes={attributes}
      />
  )
}

export default ClaimServiceCenterForm
