import { BooleanContainer, BooleanOption } from './boolean.style'

function Boolean ({
  disabled,
  selected,
  options,
  onChangeHandler
}) {
  return (
    <BooleanContainer>
      {
        options.map(({ label, value }) => {
          return (
            <BooleanOption
              active={value === selected}
              key={value}
              onClick={() => !disabled && onChangeHandler(value)}
            >
              {label}
            </BooleanOption>
          )
        })
      }
    </BooleanContainer>
  )
}

export default Boolean
