import { useState, useEffect } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { FormattedMessage } from 'react-intl'
import claimActions from '../../redux/claim/actions'
import { LANG_STRINGS } from '../../constants/lang'
import {
  useBengkelnetProvinceList,
  useBengkelnetCityList,
  useBengkelnetWorkshopList
} from '../../request/query/bengkelnet'
import SelectDropdown from '../SelectV2/selectV2'
import IntlMessages from '../utility/intlMessages'
import Loader from '../Loader'
import {
  ClaimBengkelWorkshopFormContainer,
  DropdownContainer,
  ErrorText,
  Form,
  FormTitle,
  ReadOnlyText,
  SubmitButton,
  Title
} from './styles'

const PROVINCE_NAME = 'sc_province'
const CITY_NAME = 'sc_city'
const WORKSHOP_NAME = 'sc_workshop'

function ClaimBengkelWorkshopForm ({
  formName,
  claimId,
  description,
  attributes,
  showSubmitButton
}) {
  const dispatch = useDispatch()
  const [values, setValues] = useState({})
  const [errors, setErrors] = useState({})
  const [cityTriggered, setCityTriggered] = useState(false)
  const [workshopTriggered, setWorkshopTriggered] = useState(false)
  const saveFormLoading = useSelector((state) => state.Claim.formLoadingStates[formName])

  const provinceAttr = attributes?.find((a) => a.name === PROVINCE_NAME) || {}
  const cityAttr = attributes?.find((a) => a.name === CITY_NAME) || {}
  const workshopAttr = attributes?.find((a) => a.name === WORKSHOP_NAME) || {}

  const { data: provinceData, isLoading: provinceLoading } = useBengkelnetProvinceList({
    enabled: showSubmitButton
  })
  const { data: cityData, isLoading: cityLoading } = useBengkelnetCityList(values[PROVINCE_NAME], {
    enabled: showSubmitButton && !!values[PROVINCE_NAME]
  })
  const { data: workshopData, isLoading: workshopLoading } = useBengkelnetWorkshopList(
    values[PROVINCE_NAME],
    values[CITY_NAME],
    claimId,
    { enabled: showSubmitButton && !!values[PROVINCE_NAME] && !!values[CITY_NAME]}
  )

  useEffect(() => {
    if (!claimId || showSubmitButton) return
    setValues({
      [PROVINCE_NAME]: provinceAttr.value || null,
      [CITY_NAME]: cityAttr.value || null,
      [WORKSHOP_NAME]: workshopAttr.value || null
    })
  }, [claimId, showSubmitButton])

  useEffect(() => {
    if (!claimId || !showSubmitButton || !provinceAttr.value) return
    if (provinceData?.data) {
      const match = provinceData.data.find(p => p.ProvinceName === provinceAttr.value)
      setValues({
        [PROVINCE_NAME]: match?.ProvinceId || null,
        [CITY_NAME]: null,
        [WORKSHOP_NAME]: null
      })
    }
  }, [claimId, showSubmitButton, provinceData])

  useEffect(() => {
    if (!claimId || !showSubmitButton || !cityAttr.value || !cityData?.data) return
    const match = cityData.data.find(c => c.CityName === cityAttr.value)
    if (match) {
      setValues(prev => ({ ...prev, [CITY_NAME]: match.CityID, [WORKSHOP_NAME]: null }))
    }
  }, [claimId, showSubmitButton, cityData])

  useEffect(() => {
    if (!claimId || !showSubmitButton || !workshopAttr.value || !workshopData?.data) return
    const match = workshopData.data.find(w =>
      (w.WorkshopName || w.workshop_name || w.name || w.Name) === workshopAttr.value
    )
    if (match) {
      setValues(prev => ({
        ...prev,
        [WORKSHOP_NAME]: match.WorkshopId || match.WorkshopID || match.workshop_id || match.code || match.Code
      }))
    }
  }, [claimId, showSubmitButton, workshopData])

  const provinceOptions = (provinceData?.data || []).map((p) => ({
    value: p.ProvinceId,
    displayName: p.ProvinceName
  }))

  const selectedProvince = provinceData?.data?.find(
    (p) => p.ProvinceId === values[PROVINCE_NAME]
  )

  const cityOptions = (cityData?.data || [])
    .filter((c) => !selectedProvince || c.ProvinceName === selectedProvince.ProvinceName)
    .map((c) => ({
      value: c.CityID,
      displayName: c.CityName
    }))

  const workshopOptions = (workshopData?.data || []).map((w) => ({
    value: w.WorkshopId || w.WorkshopID || w.workshop_id || w.code || w.Code,
    displayName: w.WorkshopName || w.workshop_name || w.name || w.Name
  }))

  const provinceChangeHandler = (value) => {
    setValues({
      [PROVINCE_NAME]: value,
      [CITY_NAME]: null,
      [WORKSHOP_NAME]: null
    })
    setCityTriggered(true)
    setWorkshopTriggered(false)
    setErrors({})
  }

  const cityChangeHandler = (value) => {
    setValues((prev) => ({
      ...prev,
      [CITY_NAME]: value,
      [WORKSHOP_NAME]: null
    }))
    setWorkshopTriggered(true)
    setErrors({})
  }

  const workshopChangeHandler = (value) => {
    setValues((prev) => ({
      ...prev,
      [WORKSHOP_NAME]: value
    }))
    setErrors({})
  }

  const validateFields = () => {
    const newErrors = {}
    attributes.forEach((attr) => {
      if (attr.required && !values[attr.name]) {
        newErrors[attr.name] = LANG_STRINGS.required
      }
    })
    setErrors(newErrors)
    return Object.keys(newErrors).length > 0
  }

  const saveGenericForm = () => {
    const lookupDisplay = (options, value) => {
      const match = options.find(o => o.value === value)
      return match ? match.displayName : value
    }

    const transformed = {
      ...values,
      [`${PROVINCE_NAME}_display_value`]: lookupDisplay(provinceOptions, values[PROVINCE_NAME]),
      [`${CITY_NAME}_display_value`]: lookupDisplay(cityOptions, values[CITY_NAME]),
      [`${WORKSHOP_NAME}_display_value`]: lookupDisplay(workshopOptions, values[WORKSHOP_NAME])
    }

    dispatch(claimActions.saveGenericAttributes({
      payload: transformed,
      claim_id: claimId,
      form: formName,
      source: 'direct'
    }))
  }

  const onSubmitHandler = (e) => {
    e.preventDefault()
    const err = validateFields()
    if (err) return
    saveGenericForm()
  }

  const renderDropdown = (label, value, options, loading, onChange, disabled, error) => (
    <DropdownContainer>
      <SelectDropdown
        showSearch
        loading={loading}
        value={value}
        changedValue={value}
        error={error}
        disabled={disabled}
        options={options}
        placeholder={label}
        onSelect={(val) => onChange(val)}
      />
      {error ? (
        <ErrorText>
          <IntlMessages id={error} />
        </ErrorText>
      ) : null}
    </DropdownContainer>
  )

  return (
    <ClaimBengkelWorkshopFormContainer>
      {description && (
        <FormTitle>
          <IntlMessages id={description} />
        </FormTitle>
      )}
      <Form>
        <Title required={provinceAttr.required}>
          <IntlMessages id={provinceAttr.label} />
        </Title>
        {showSubmitButton
          ? renderDropdown(
              provinceAttr.label,
              values[PROVINCE_NAME],
              provinceOptions,
              provinceLoading,
              provinceChangeHandler,
              false,
              errors[PROVINCE_NAME]
            )
          : <ReadOnlyText>{values[PROVINCE_NAME]}</ReadOnlyText>}
      </Form>
      <Form>
        <Title required={cityAttr.required}>
          <IntlMessages id={cityAttr.label} />
        </Title>
        {showSubmitButton
          ? renderDropdown(
              cityAttr.label,
              values[CITY_NAME],
              cityOptions,
              cityTriggered && cityLoading,
              cityChangeHandler,
              !values[PROVINCE_NAME],
              errors[CITY_NAME]
            )
          : <ReadOnlyText>{values[CITY_NAME]}</ReadOnlyText>}
      </Form>
      <Form>
        <Title required={workshopAttr.required}>
          <IntlMessages id={workshopAttr.label} />
        </Title>
        {showSubmitButton
          ? renderDropdown(
              workshopAttr.label,
              values[WORKSHOP_NAME],
              workshopOptions,
              workshopTriggered && workshopLoading,
              workshopChangeHandler,
              !values[CITY_NAME],
              errors[WORKSHOP_NAME]
            )
          : <ReadOnlyText>{values[WORKSHOP_NAME]}</ReadOnlyText>}
      </Form>
      {showSubmitButton && (
        <SubmitButton onClick={onSubmitHandler}>
          {saveFormLoading ? <Loader /> : null}
          <FormattedMessage id={LANG_STRINGS.submit} />
        </SubmitButton>
      )}
    </ClaimBengkelWorkshopFormContainer>
  )
}

export default ClaimBengkelWorkshopForm
