/* eslint-disable react/jsx-filename-extension */
import { message } from "antd";
import debounce from "lodash/debounce";
import find from "lodash/find";
import { useMemo, useState } from "react";
import { useDispatch, useSelector } from "react-redux";

import { FORMFIELDTYPES } from "../../constants/constants";
import { LANG_STRINGS } from "../../constants/lang";
import { CLAIM_LANG } from "../../containers/Claim/constants";
import { normalizeToUtcMidnight } from "../../helpers/formatDate";
import { useRemoveLoadingActionsHelper } from "../../helpers/utility";
import claimActions from "../../redux/claim/actions";
import DynamicForm from "../DynamicForm/dynamicForm";
import Loader from "../Loader";
import IntlMessages from "../utility/intlMessages";
import {
  ErrorText,
  FormWrapper,
  SalvageAddressContainer,
  SubmitButton,
} from "./claimGenricForm.style";

function ClaimGenricForm({
  formData = [],
  claimId,
  formName,
  isSalvage,
  form,
  showSubmitButton,
}) {
  const dispatch = useDispatch();

  const initializeValues = () => {
    const savedFormData = localStorage.getItem(`formData-${claimId}`);
    if (savedFormData) {
      return JSON.parse(savedFormData);
    }

    const values = {};
    formData.forEach((attr) => {
      values[attr.name] = attr.value;
    });
    return values;
  };

  const initiazeErrorValues = () => {
    const errors = {};
    formData.forEach((attr) => {
      if (attr.status === "invalid") {
        errors[attr.name] = attr.reject_remarks;
      }
    });
    return errors;
  };

  const [values, setValues] = useState(initializeValues);
  const [errors, setErrors] = useState(initiazeErrorValues);
  const [validateChronologyStates, setValidateChronlogyStates] = useState({});

  const saveFormLoading = useSelector(
    (state) => state.Claim.formLoadingStates[formName]
  );

  const isSaveGenricAttributeStatusError = useSelector(
    (state) => state.Claim.saveGenericAttributesStatus[formName]
  );

  const savePartialFormLoading = useRemoveLoadingActionsHelper(
    claimActions.POST_SALVAGE_FORMS_REQUEST
  );

  const language = useSelector((state) => state.App.language.locale);

  const claimdetailsData = useSelector((state) => state.Claim.claimDetails);

  const validateNIK = (val) => {
    // General validation for 16 characters
    if (val && val.length !== 16) {
      return "Invalid NIK (NIK harus berisi 16 karakter)";
    }
    return "";
  };

  const validateField = (attr, value) => {
    if (!attr) return "";

    switch (attr.type) {
      case FORMFIELDTYPES.BOOLEAN:
        return [true, false].includes(value) ? "" : LANG_STRINGS.required;

      case FORMFIELDTYPES.DATE: {
        const dateValue = new Date(value);
        const startDate = attr.calendar_date_starting_from
          ? new Date(attr.calendar_date_starting_from)
          : null;
        const endDate = attr.calendar_date_end_on
          ? new Date(attr.calendar_date_end_on)
          : null;

        if (Number.isNaN(dateValue.getTime())) {
          return "Invalid date format";
        }

        if (startDate && !endDate && dateValue < startDate) {
          return `The date must be on or after ${attr.calendar_date_starting_from}`;
        }

        if (endDate && !startDate && dateValue > endDate) {
          return `The date must be on or before ${attr.calendar_date_end_on}`;
        }

        if (
          startDate &&
          endDate &&
          (dateValue < startDate || dateValue > endDate)
        ) {
          return `The date must be between ${attr.calendar_date_starting_from} and ${attr.calendar_date_end_on}`;
        }

        break;
      }

      default:
        break;
    }

    // General validations
    if (!value && attr.required) return LANG_STRINGS.required;
    if (attr.regex && !new RegExp(attr.regex).test(value)) {
      return LANG_STRINGS.regexIncorrect;
    }
    if (attr.required && value && value.length === 0)
      return LANG_STRINGS.required;

    if (attr.name === "nik_number") {
      const error = validateNIK(value);
      if (error) return error;
    }

    if (attr.name === "cardamages_front_back") {
      let imageCount = 0;
      if (Array.isArray(value)) {
        imageCount = value.length;
      } else if (value) {
        imageCount = 1;
      }

      if (imageCount < 4) {
        return "Car damages must have at least 4 images";
      }
    }

    return "";
  };

  const validateFields = () => {
    const newErrors = {};
    let flag = false;

    formData.forEach((attr) => {
      const err = validateField(attr, values[attr.name]);
      newErrors[attr.name] = err;
      if (err) flag = true;
    });

    // Additional cross-field validation: ensure cardamages_front_back has >= 4 images
    try {
      const fieldsName = formData.map((f) => f.name);
      if (fieldsName.includes("cardamages_front_back")) {
        const carDamagesAttribute = formData.find(
          (a) => a.name === "cardamages_front_back"
        );
        const carDamagesValue =
          values.cardamages_front_back ||
          (carDamagesAttribute && carDamagesAttribute.value);
        let imageCount = 0;

        if (Array.isArray(carDamagesValue)) {
          imageCount = carDamagesValue.length;
        } else if (carDamagesValue) {
          imageCount = 1;
        }

        if (imageCount < 4) {
          newErrors.cardamages_front_back =
            "Car damages must have at least 4 images";
          message.error("Car damages must have at least 4 images");
          flag = true;
        }
      }
    } catch (err) {
      // non-fatal; if something unexpected, don't block other validations
      // eslint-disable-next-line no-console
      console.error("car damages validation error", err);
    }

    setErrors(newErrors);
    return flag;
  };

  const verifyErrorStatus = (name, value) => {
    const field = formData.find((item) => item.name === name);
    const error = validateField(field, value);
    setErrors({ ...errors, [name]: error });
  };

  const saveFormDataToLocalStorage = useMemo(
    () =>
      debounce((data) => {
        localStorage.setItem(`formData-${claimId}`, JSON.stringify(data));
      }, 500),
    [claimId]
  );

  const onChangeHandler = ({ value, name }) => {
    const newValue = { ...values, [name]: value };
    if (errors[name]) verifyErrorStatus(name, value);
    saveFormDataToLocalStorage(newValue);
    setValues(newValue);
  };

  const saveGenricForm = () => {
    const payload = { ...values }
    if(payload.date_of_accident){
      payload.date_of_accident = normalizeToUtcMidnight(payload.date_of_accident)
    }
    if(payload.date_of_incident){
      payload.date_of_incident = normalizeToUtcMidnight(payload.date_of_incident)
    }
    dispatch(
      claimActions.saveGenericAttributes({
        payload,
        claim_id: claimId,
        form: formName,
        source: "direct",
      })
    );
    localStorage.removeItem(`formData-${claimId}`);
  };

  const saveSalvageForm = () => {
    const { salvage_slug: salvageSlug, salvage_status: salvageStatus } =
      form || {};
    const trackingNumber = values[`tracking_no---${salvageSlug}`];
    values.tracking_no = trackingNumber || values.tracking_no;
    values.source = "direct";
    delete values[`tracking_no---${salvageSlug}`];

    dispatch(
      claimActions.postSalvageForms({
        payload: values,
        claim_id: claimId,
        form: formName,
        salvage_slug: salvageSlug,
        salvage_status: salvageStatus,
      })
    );
  };

  const onSubmitHandler = (e) => {
    e.preventDefault();
    const err = validateFields();
    if (err) return;
    if (isSalvage) {
      saveSalvageForm();
      return;
    }
    saveGenricForm();
  };

  const onImageUplaodSuccess = (url, name) => {
    onChangeHandler({ value: url, name });
    dispatch(
      claimActions.updateFormAttribute({
        body: {
          [name]: url,
        },
        params: {
          form: formName,
          claimId,
        },
      })
    );
  };

  const changeErrorStatus = ({ name, error }) => {
    setErrors((prev) => ({ ...prev, [name]: error }));
  };

  const salvageAddress =
    form && form.attributes ? find(form.attributes, { name: "address" }) : null;

  return (
    <FormWrapper>
      {isSalvage ? (
        <SalvageAddressContainer>
          <IntlMessages
            id={
              salvageAddress
                ? salvageAddress.label
                : CLAIM_LANG.salvageFormTitle
            }
            defaultMessage={
              salvageAddress
                ? salvageAddress.label
                : CLAIM_LANG.salvageFormTitle
            }
          />
        </SalvageAddressContainer>
      ) : null}

      <DynamicForm
        language={language}
        errors={errors}
        values={values}
        formData={formData}
        claimId={claimId}
        formName={formName}
        onChangeHandler={onChangeHandler}
        changeErrorStatus={changeErrorStatus}
        onImageUplaodSuccess={onImageUplaodSuccess}
        validateChronologyStates={validateChronologyStates}
        setValidateChronlogyStates={setValidateChronlogyStates}
        partner={claimdetailsData.partner_id}
        productKey={claimdetailsData.product_key}
        packageName={claimdetailsData.package_code}
      />

      {isSaveGenricAttributeStatusError && (
        <ErrorText>{isSaveGenricAttributeStatusError}</ErrorText>
      )}

      {showSubmitButton && (
        <SubmitButton onClick={onSubmitHandler}>
          {saveFormLoading || savePartialFormLoading ? <Loader /> : null}
          <IntlMessages id={LANG_STRINGS.submit} />
        </SubmitButton>
      )}
    </FormWrapper>
  );
}

export default ClaimGenricForm;
