import { useIntl } from 'react-intl'
import ClaimHeaderUserDetails from '../../../components/ClaimHeaderUserDetails'
import ClaimTimeline from '../../../components/ClaimTimeline'
import { LANG_STRINGS } from '../../../constants/lang'
import { DocumentIcon, ProfileIcon } from '../../../image'
import {
  ClaimDetailHeaderContainer,
  ClaimDetailMainContent
} from './claimDetailHeader.style'
import { useIsMobile } from '../../../hooks/useIsMobile'
import { STATUS_GROUP_DOC_REPROCESS, STATUS_GROUP_INITIATED } from '../../../constants/constants'

function ClaimDetailHeader ({
  claimData
}) {
  const intl = useIntl()
  const isMobile = useIsMobile()
  const {
    policy_holder_name: insured,
    claim_no: claimNo,
    max_doc_submission_date,
    max_reprocess_doc_submission_date,
    status_group: claimStatus
  } = claimData

  const maxDocSubmissionDate = 
  claimStatus === "initiated"
    ? max_doc_submission_date
    : claimStatus === "document_reprocess"
    ? max_reprocess_doc_submission_date
    : null;


  const headerMiddleText = maxDocSubmissionDate && [STATUS_GROUP_INITIATED, STATUS_GROUP_DOC_REPROCESS].includes(claimStatus) && intl.formatMessage(
    {
      id: LANG_STRINGS.fillTheDocumentsByDate,
      defaultMessage: LANG_STRINGS.fillTheDocumentsByDate
    },
    {
      maxDocSubmissionDate
    }
  )

  return (
    <ClaimDetailHeaderContainer>
      <ClaimDetailMainContent>
        <ClaimTimeline claimData={claimData} />
        <ClaimHeaderUserDetails
          isMobile={isMobile}
          leftSideIcon={ProfileIcon}
          leftSubTitle={LANG_STRINGS.insured}
          leftTitle={insured}
          middleText={headerMiddleText}
          rightSideIcon={DocumentIcon}
          rightSubTitle={LANG_STRINGS.claimId}
          rightTitle={claimNo}

        />
      </ClaimDetailMainContent>
    </ClaimDetailHeaderContainer>
  )
}

export default ClaimDetailHeader
