import React, { useState, useEffect, useRef } from 'react'
import styled from 'styled-components'
import { COLORS } from '../../constants/colors'
import useComponentVisible from '../../hooks/useComponentVisible'
import Loader from '../Loader'
import { ArrowSelection } from '../../image'

const DropdownContainer = styled.div`
  position: relative;
  width: 100%;
`

const DropdownHeader = styled.div`
  height: 56px;
  background: #ffffff;
  border: ${props => props.error ? `1px solid ${COLORS.crimsonRed}` : `1px solid ${COLORS.disabledLightGrey}`};
  padding: 10px;
  cursor: pointer;
  justify-content: center;
  align-items: center;
  display: flex;
  flex-direction: column;
  padding: 8px 16px;
  align-items: center;
  gap: 8px;
  border-radius: 8px;
  border: 1px solid ${props => props.error ? COLORS.crimsonRed : COLORS.disabledLightGrey};
  background: var(--Monochrome-White, #FFF);
  border-bottom: ${props => props.isOpen ? '0px' : `1px solid ${props.error ? COLORS.crimsonRed : COLORS.disabledLightGrey}`};
  color: ${props => props.value ? COLORS.black : COLORS.monoChromeGrey};
  text-overflow: ellipsis;
  overflow: hidden;

  font-size: 14px;
  font-weight: 500;
  line-height: 16px;
  cursor: ${props => props.disabled ? 'not-allowed' : 'inherit'};
`
const DropdownListContainer = styled.div`
  position: absolute;
  width: 100%;
  background: #ffffff;
  border: 1px solid #d9d9d9;
  border-top: none;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
  z-index: 1000;
  border-bottom-left-radius: 8px;
  border-bottom-right-radius: 8px;
  max-height: 200px;
  overflow: auto;
`

const DropdownList = styled.ul`
  list-style: none;
  margin: 0;
  padding: 0;
  font-family: Mulish;
  font-size: 14px;
  font-style: normal;
  font-weight: 500;
  line-height: 16px; /* 114.286% */
`

const ListItem = styled.li`
  padding: 10px;
  cursor: pointer;
  &:hover {
    background: #f0f0f0;
  }
`

const SearchInput = styled.input`
  width: 100%;
  padding: 8px 12px;
  border: none;
  border-bottom: 1px solid #d9d9d9;
  font-family: Mulish;
  font-size: 14px;
  outline: none;
  box-sizing: border-box;
  &::placeholder {
    color: #999;
  }
`

const Arrow = styled.img`
  width: 20px;
  height: 20px;
`

export const SelectText = styled.div`
    line-height: 24px;
    display: flex;
    text-overflow: ellipsis;
    height: 100%;
    width: 100%;
    overflow: hidden;
    line-height: 16px;
    height: 16px;
`

export const LabelTitle = styled.div`
    color: var(--Monochrome-Dark-Grey, #999);

  /* Caption/Caption Semibold */
  font-family: Mulish;
  font-size: 12px;
  font-style: normal;
  font-weight: 600;
  line-height: 16px; /* 133.333% */
  width: 100%;
`

const SelectDropdown = ({ options, placeholder, onSelect, disabled, error, value, loading, title, showSearch }) => {
  const { ref, isComponentVisible, setIsComponentVisible } = useComponentVisible()
  const [selectedOption, setSelectedOption] = useState(value)
  const [searchText, setSearchText] = useState('')
  const searchRef = useRef(null)

  useEffect(() => {
    setSelectedOption(value)
  }, [value])

  useEffect(() => {
    if (isComponentVisible && showSearch && searchRef.current) {
      searchRef.current.focus()
    }
    if (!isComponentVisible) {
      setSearchText('')
    }
  }, [isComponentVisible, showSearch])

  const toggling = (e) => {
    e.stopPropagation()
    if (disabled || loading) return
    setSearchText('')
    setIsComponentVisible((open) => !open)
  }

  const onOptionClicked = value => () => {
    setSelectedOption(value)
    setIsComponentVisible(false)
    if (value !== selectedOption) {
      onSelect(value)
    }
  }

  const filteredOptions = showSearch && searchText
    ? options?.filter((opt) =>
      (opt.displayName || '').toLowerCase().includes(searchText.toLowerCase())
    )
    : options

  const onSearchKeyDown = (e) => {
    e.stopPropagation()
  }

  const isSonethingSelected = !(selectedOption === null || selectedOption === undefined)

  return (
    <DropdownContainer >
      <DropdownHeader
        disabled={disabled}
        ref={ref}
        error={error}
        onClick={toggling}
        value={isSonethingSelected}
      >
        {
          title && (
            <LabelTitle>
              {title}
            </LabelTitle>
          )
        }

        <div style={{ display: 'flex', width: '100%', textOverflow: 'clip' }}>
          <SelectText>
            {(options?.find((op) => op.value === selectedOption)?.displayName || selectedOption) ||
          placeholder
            }
          </SelectText>
          {
            loading
              ? <Loader />
              : <Arrow src={ArrowSelection} isOpen={isComponentVisible} />
          }
        </div>
      </DropdownHeader>
      {isComponentVisible && (
        <DropdownListContainer onClick={(e) => e.stopPropagation()}>
          {showSearch && (
            <SearchInput
              ref={searchRef}
              type='text'
              placeholder='Cari...'
              value={searchText}
              onChange={(e) => setSearchText(e.target.value)}
              onKeyDown={onSearchKeyDown}
            />
          )}
          <DropdownList>
            {filteredOptions?.map(({ value, displayName }) => (
              <ListItem key={value} onClick={onOptionClicked(value)}>
                {displayName}
              </ListItem>
            ))}
          </DropdownList>
        </DropdownListContainer>
      )}
    </DropdownContainer>
  )
}

export default SelectDropdown
