import { useRef, useState, useEffect, useCallback } from 'react'

let idCounter = 0

export const useCameraCapture = ({ multiple } = {}) => {
  const videoRef = useRef(null)
  const streamRef = useRef(null)
  const [capturedPhotos, setCapturedPhotos] = useState([])
  const [facingMode, setFacingMode] = useState('environment')

  const startCamera = useCallback(async (facing) => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop())
      streamRef.current = null
    }
    const perm = await navigator.permissions?.query?.({ name: 'camera' })
    if (perm && perm.state === 'denied') {
      const err = new Error('Camera access blocked')
      err.name = 'CameraPermissionBlocked'
      throw err
    }
    const constraints = {
      video: {
        facingMode: facing || 'environment',
        width: { ideal: 2560 },
        height: { ideal: 1440 },
      },
      audio: false,
    }
    const stream = await navigator.mediaDevices.getUserMedia(constraints)
    streamRef.current = stream
    if (videoRef.current) {
      videoRef.current.srcObject = stream
    }
  }, [])

  const stopCamera = useCallback(() => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop())
      streamRef.current = null
    }
  }, [])

  const capture = useCallback(() => {
    const video = videoRef.current
    if (!video) return null

    const vw = video.videoWidth
    const vh = video.videoHeight
    const ratio = 2 / 3
    let cropW, cropH, cropX, cropY

    if (vw / vh > ratio) {
      cropH = vh
      cropW = cropH * ratio
      cropX = (vw - cropW) / 2
      cropY = 0
    } else {
      cropW = vw
      cropH = cropW / ratio
      cropX = 0
      cropY = (vh - cropH) / 2
    }

    const canvas = document.createElement('canvas')
    canvas.width = Math.round(cropW)
    canvas.height = Math.round(cropH)
    const ctx = canvas.getContext('2d')
    if (!ctx) return null
    ctx.drawImage(video, cropX, cropY, cropW, cropH, 0, 0, cropW, cropH)

    return new Promise((resolve) => {
      canvas.toBlob(
        (blob) => {
          if (!blob) {
            resolve(null)
            return
          }
          const file = new File([blob], `capture_${Date.now()}.jpg`, {
            type: 'image/jpeg',
          })
          resolve(file)
        },
        'image/jpeg',
        0.92,
      )
    })
  }, [])

  const addPhoto = useCallback(
    (file, captureTimestamp) => {
      const id = ++idCounter
      const url = URL.createObjectURL(file)
      const photo = { id, file, url, captureTimestamp }
      if (!multiple) {
        setCapturedPhotos([photo])
      } else {
        setCapturedPhotos((prev) => [...prev, photo])
      }
      return photo
    },
    [multiple],
  )

  const removePhoto = useCallback((id) => {
    setCapturedPhotos((prev) => {
      const idx = prev.findIndex((p) => p.id === id)
      if (idx === -1) return prev
      URL.revokeObjectURL(prev[idx].url)
      return prev.filter((p) => p.id !== id)
    })
  }, [])

  const reset = useCallback(() => {
    stopCamera()
    setCapturedPhotos((prev) => {
      prev.forEach((p) => URL.revokeObjectURL(p.url))
      return []
    })
  }, [stopCamera])

  const switchCamera = useCallback(async () => {
    const newFacing = facingMode === 'environment' ? 'user' : 'environment'
    setFacingMode(newFacing)
    await startCamera(newFacing)
  }, [facingMode, startCamera])

  useEffect(() => {
    return () => {
      stopCamera()
    }
  }, [stopCamera])

  return {
    videoRef,
    capturedPhotos,
    facingMode,
    startCamera,
    stopCamera,
    switchCamera,
    capture,
    addPhoto,
    removePhoto,
    reset,
  }
}
