export const TimelineLine = styled.div`
  margin: 0 auto;
  width: 100%;
  height: 2px;
  border-radius: 8px;
  background-color: ${props => {
    if (props.lineStatus === 'idle') {
      return COLORS.disabledLightGrey
    } else if (props.lineStatus === 'complete') {
      return COLORS.grassGreen
    } else if (props.lineStatus === 'process') {
      return COLORS.darkYellow
    } else if (props.lineStatus === 'reject') {
      return COLORS.tapTapHeartRed
    }
  }};
  color: ${props => {
    if (props.lineStatus === 'idle') {
      return ``
    } else if (props.lineStatus === 'complete') {
      return COLORS.grassGreen
    } else if (props.lineStatus === 'process') {
      return COLORS.darkYellow
    } else if (props.lineStatus === 'reject') {
      return COLORS.tapTapHeartRed
    }
  }};
`

