import { FORMFIELDTYPES } from '../../constants'
import { ProfileIcon, bankIcon, creditCardIcon } from '../../image'
import IntlMessages from '../utility/intlMessages'
import {
  Attribute,
  AttributeContainer,
  ClaimBankFormValuesContainer,
  Icon,
  IconContainer,
  LabelContainer,
  Title,
  ValueContainer
} from './claimBankForm.style'

const iconsMap = {
  'account_number': creditCardIcon,
  'bank_name': bankIcon,
  'account_holder_name': ProfileIcon
}

function ClaimBankFormValues ({
  bankDeatilForm = {},
  bankList = []
}) {
  const { attributes = [], title = '' } = bankDeatilForm
  return (
    <ClaimBankFormValuesContainer>
      <Title >
        <IntlMessages id={title} />
      </Title>
      <AttributeContainer>
        {attributes.map(({ value, label, name, options, type }) => {
          let val = value
          if (type === FORMFIELDTYPES.choices) {
            val = bankList?.find(([code]) => code === val)?.[1]
          }
          return (
            <Attribute key={name}>
              <IconContainer>
                <Icon src={iconsMap[name]} />
              </IconContainer>
              <div>
                <LabelContainer>
                  <IntlMessages id={label} />
                </LabelContainer>
                <ValueContainer>{val}</ValueContainer>
              </div>
            </Attribute>
          )
        })}
      </AttributeContainer>

    </ClaimBankFormValuesContainer>
  )
}

export default ClaimBankFormValues
