import {
  TimelineContainer
} from './elements'
import TimelineItem from '../TimelineItem'
import PropTypes from 'prop-types'
import { useEffect, useState } from 'react'

const Timeline = ({ children }) => {
  const [childrenArr, setChildrenArr] = useState([])

  useEffect(() => {
    if (children.length === undefined) {
      setChildrenArr([children])
    } else {
      setChildrenArr(children)
    }
  }, [children])

  return (
    <TimelineContainer>
      {childrenArr?.map((child, idx) => (
        <TimelineItem
          key={idx}
          isLastChild={idx === childrenArr.length - 1}
          lineStatus={children[idx + 1]?.props.status !== undefined ? children[idx + 1].props.status : 'idle'}
          {...child.props}
        />
      ))}
    </TimelineContainer>
  )
}

Timeline.propTypes = {
  children: PropTypes.node
}

export default Timeline
