import { useIsMobile } from '../../hooks/useIsMobile'
import {
  TimelineContainer,
  TimelineIconIdle,
  TimelineIconComplete,
  TimelineIconProcess,
  TimelineIconReject,
  TimelineTitle,
  TimelineTitleWrapper,
  TimelineLine,
  Center,
  TimeStickContainer
} from './elements'
import PropTypes from 'prop-types'

const TimelineItem = ({ status, lineStatus, title, isLastChild }) => {
  const isMobile = useIsMobile()
  const getStatusIcon = (status) => {
    if (status === 'idle') {
      return (<TimelineIconIdle />)
    } else if (status === 'complete') {
      return (<TimelineIconComplete />)
    } else if (status === 'process') {
      return (<TimelineIconProcess />)
    } else if (status === 'reject') {
      return (<TimelineIconReject />)
    } else {
      return (<TimelineIconIdle />)
    }
  }

  return (
    <TimelineContainer>
      <TimelineTitleWrapper isMobile={isMobile}>
        <Center>
          {getStatusIcon(status)}
        </Center>
        <TimelineTitle>
          {title}
        </TimelineTitle>
      </TimelineTitleWrapper>
      {isLastChild ? ('') : (
        <TimeStickContainer isMobile={isMobile}>
          <TimelineLine lineStatus={lineStatus} />
        </TimeStickContainer>
      )}
    </TimelineContainer>
  )
}

TimelineItem.propTypes = {
  status: PropTypes.string,
  lineStatus: PropTypes.string,
  title: PropTypes.string,
  isLastChild: PropTypes.bool
}

export default TimelineItem
