import React, { useState } from 'react'
import { useIntl } from 'react-intl'
import PropTypes from 'prop-types'

import {
  Wrapper,
  AsteriskContainer,
  AsteriskItem,
  AsteriskItemContainer
} from './asterisk.style'
import { ViewOnIcon } from '../../image'

const Asterisk = (props) => {
  const { placeholder, width, onChange = () => { }, onBlur, value, error } = props
  const intl = useIntl()
  const [type, setType] = useState('password')

  const changeTextInputType = () => {
    setType(type => type === 'password' ? 'text' : 'password')
  }
  return (
    <Wrapper>
      <AsteriskContainer error={error}>
        <AsteriskItemContainer width={width}>
          <AsteriskItem
            onCopy={(e) => e.preventDefault()}
            type={type}
            value={value}
            id={`${props.name}~input`}
            data-attr-slug={`${props.name}~${props.form.name}~input`}
            disabled={props.disabled}
            pattern={props.pattern}
            onBlur={onBlur}
            inputMode={props.inputMode}
            onChange={(event) => onChange({ value: event.target.value, name: props.name })}
            placeholder={intl.formatMessage({
              id: placeholder || ' ',
              defaultMessage: placeholder || ' '
            })}
          />
          <img src={ViewOnIcon} onClick={changeTextInputType} />
        </AsteriskItemContainer>
      </AsteriskContainer>
    </Wrapper>

  )
}

Asterisk.propTypes = {
  label: PropTypes.string.isRequired,
  name: PropTypes.string.isRequired
}

Asterisk.defaultProps = {
}

export default Asterisk
