import { useParams } from 'react-router'
import { useEffect, useState } from 'react'
import { useDispatch, useSelector } from 'react-redux'

import {
  ClaimServiceCenterFormContainer,
  DropdownContainer,
  ErrorText,
  Flex,
  Form,
  NoBrandSpecializationModalText,
  RejectRemarksContainer,
  RejectRemarksText,
  SubmitButton,
  Title

} from './ClaimServiceStyle'
import claimActions from '../../redux/claim/actions'
import { servicecenterFormAttributes } from '../../constants/constants'
import SelectDropdown from '../SelectV2/selectV2'
import IntlMessages from '../utility/intlMessages'
import { useRemoveErrorActionsHelper, useRemoveLoadingActionsHelper } from '../../helpers/utility'
import { LANG_STRINGS } from '../../constants/lang'
import Loader from '../Loader'
import { FormattedMessage } from 'react-intl'
import CustomModal from '../Modal/Modal'
import { AlertRedIcon, InformationFilled } from '../../image'

function AddressFormWrapper ({
  formName,
  attributes
}) {
  const {
    brandConst,
    provinceConst,
    cityConst,
    postalCodeConst,
    serviceCenterConst,
    serviceBranchCenterConst
  } = servicecenterFormAttributes
  const isBrandOptionExist = attributes?.find(({ name }) => name === brandConst)
  const dispatch = useDispatch()
  const { id } = useParams()

  const [errors, setErrors] = useState({})
  const [values, setValues] = useState({})
  const [noBrandSpecializationModal, setNoBrandSpecialization] = useState(false)

  const brandOptions = useSelector((state) => state.Claim.serviceCenterBrandList)
  const provinceOptions = useSelector((state) => state.Claim.provinceList)
  const cityListOnProvince = useSelector((state) => state.Claim.cityListOnProvince)
  const postalCodeList = useSelector((state) => state.Claim.postalCodeList)
  const serviceCenterList = useSelector((state) => state.Claim.serviceCenterList)
  const branchList = useSelector((state) => state.Claim.branchList)
  const saveFormLoading = useSelector((state) => state.Claim.formLoadingStates[formName])
  const provinceErrorMessage = useSelector((state) => state.Claim.provinceErrorMessage)

  const branchGetError = useRemoveErrorActionsHelper(claimActions.GET_SERVICE_CENTER_BRANCH_LIST_REQUEST)

  useEffect(() => {
    if (branchGetError) {
      setNoBrandSpecialization(true)
    }
  }, [branchGetError])

  const optionsMap = {
    [brandConst]: brandOptions,
    [provinceConst]: provinceOptions,
    [cityConst]: cityListOnProvince,
    [postalCodeConst]: postalCodeList,
    [serviceCenterConst]: serviceCenterList,
    [serviceBranchCenterConst]: branchList
  }

  const getBrandList = () => {
    dispatch(claimActions.getServiceCenterBrandList())
  }

  const getProvinceOptions = () => {
    dispatch(claimActions.getProvinceList({
      claim_id: id
    }))
  }

  const getCityOptions = (value) => {
    dispatch(claimActions.getCityListInProvince(value))
  }
  const getPostalCodeOptions = (value) => {
    dispatch(claimActions.getPostalCodeList(value))
  }
  const getServiceCenterOptions = (value) => {
    dispatch(claimActions.getServiceCenterList(value))
  }
  const getBranchOptions = (value) => {
    dispatch(claimActions.getServiceCenterBranchList(value))
  }

  useEffect(() => {
    getBrandList()
    getProvinceOptions()
  }, [id])

  const provinceChangeHandler = ({ value, name }) => {
    setValues(val => ({
      [provinceConst]: value,
      [brandConst]: val[brandConst]
    }))
    setErrors((e) => ({
      [provinceConst]: '',
      [cityConst]: e[cityConst],
      [postalCodeConst]: e[postalCodeConst],
      [serviceCenterConst]: e[serviceCenterConst],
      [serviceBranchCenterConst]: e[serviceBranchCenterConst]
    }))
    getCityOptions({
      province_code: value,
      claim_id: id
    })
  }
  const cityChangeHandler = ({ value, name }) => {
    setValues((val) => ({
      [brandConst]: val[brandConst],
      [provinceConst]: val[provinceConst],
      [cityConst]: value
    }))
    setErrors((e) => ({
      [provinceConst]: '',
      [cityConst]: '',
      [postalCodeConst]: e[postalCodeConst],
      [serviceCenterConst]: e[serviceCenterConst],
      [serviceBranchCenterConst]: e[serviceBranchCenterConst]
    }))
    getPostalCodeOptions({
      province_code: values[provinceConst],
      city_code: value,
      claim_id: id
    })
  }
  const postalCodeChangeHandler = ({ value, name }) => {
    setValues((val) => ({
      [brandConst]: val[brandConst],
      [provinceConst]: val[provinceConst],
      [cityConst]: val[cityConst],
      [postalCodeConst]: value
    }))
    setErrors((e) => ({
      [provinceConst]: '',
      [cityConst]: '',
      [postalCodeConst]: '',
      [serviceCenterConst]: e[serviceCenterConst],
      [serviceBranchCenterConst]: e[serviceBranchCenterConst]
    }))
    getServiceCenterOptions({
      province_code: values[provinceConst],
      city_code: values[cityConst],
      postal_code: value,
      claim_id: id
    })
  }
  const serviceCenterChangeHandler = ({ value, name }) => {
    setValues((val) => ({
      [brandConst]: val[brandConst],
      [provinceConst]: val[provinceConst],
      [cityConst]: val[cityConst],
      [postalCodeConst]: val[postalCodeConst],
      [serviceCenterConst]: value
    }))
    setErrors((e) => ({
      [provinceConst]: '',
      [cityConst]: '',
      [postalCodeConst]: '',
      [serviceCenterConst]: '',
      [serviceBranchCenterConst]: e[serviceBranchCenterConst]
    }))
    getBranchOptions({
      brand: values[brandConst],
      province_code: values[provinceConst],
      city_code: values[cityConst],
      postal_code: values[postalCodeConst],
      service_center_code: value
    })
  }
  const branchChangeHandler = ({ value, name }) => {
    setValues((val) => ({
      [brandConst]: val[brandConst],
      [provinceConst]: val[provinceConst],
      [cityConst]: val[cityConst],
      [postalCodeConst]: val[postalCodeConst],
      [serviceCenterConst]: val[serviceCenterConst],
      [serviceBranchCenterConst]: value
    }))
    setErrors({})
  }

  const brandChangeHandler = ({ value, name }) => {
    setValues({
      [brandConst]: value
    })
    setErrors((e) => ({
      [provinceConst]: e[provinceConst],
      [cityConst]: e[cityConst],
      [postalCodeConst]: e[postalCodeConst],
      [serviceCenterConst]: e[serviceCenterConst],
      [serviceBranchCenterConst]: e[serviceBranchCenterConst]
    }))
  }

  const changeHandlerMap = {
    [brandConst]: brandChangeHandler,
    [provinceConst]: provinceChangeHandler,
    [cityConst]: cityChangeHandler,
    [postalCodeConst]: postalCodeChangeHandler,
    [serviceCenterConst]: serviceCenterChangeHandler,
    [serviceBranchCenterConst]: branchChangeHandler
  }

  const disabledMap = {
    [provinceConst]: isBrandOptionExist ? !(values[brandConst]) : false,
    [cityConst]: !values[provinceConst],
    [postalCodeConst]: !values[cityConst],
    [serviceCenterConst]: !values[postalCodeConst],
    [serviceBranchCenterConst]: !values[serviceCenterConst]
  }

  const loadingMap = {
    [brandConst]: useRemoveLoadingActionsHelper(claimActions.GET_SERVICE_CENTER_BRAND_LIST_REQUEST),
    [provinceConst]: useRemoveLoadingActionsHelper(claimActions.GET_PROVINCE_LIST_REQUEST),
    [cityConst]: useRemoveLoadingActionsHelper(claimActions.GET_CITY_LIST_ON_PROVINCE_REQUEST),
    [postalCodeConst]: useRemoveLoadingActionsHelper(claimActions.GET_POSTAL_CODE_LIST_REQUEST),
    [serviceCenterConst]: useRemoveLoadingActionsHelper(claimActions.GET_SERVICE_CENTER_LIST_REQUEST),
    [serviceBranchCenterConst]: useRemoveLoadingActionsHelper(claimActions.GET_SERVICE_CENTER_BRANCH_LIST_REQUEST)
  }

  const renderInput = (attr) => {
    const { label, name } = attr
    const options = optionsMap[name]?.map((op) => ({ ...op, displayName: decodeURI(op.displayName) }))
    const onChangeHandler = changeHandlerMap[name]
    const disabled = disabledMap[name]
    return (
      <DropdownContainer>
        <SelectDropdown
          loading={loadingMap[name]}
          value={values[name]}
          changedValue={values[name]}
          error={errors[name]}
          disabled={disabled}
          options={options}
          placeholder={<IntlMessages id={label} />}
          onSelect={(value) => onChangeHandler({ value, name })}
        />
        <ErrorText>
          <IntlMessages id={errors[name]} />
        </ErrorText>
      </DropdownContainer>
    )
  }

  const validateField = (attr, value) => {
    if (!value && attr.required) return LANG_STRINGS.required
  }
  const validateFields = () => {
    const newErrors = {}
    let flag = false
    attributes.forEach((attr) => {
      let err = validateField(attr, values[attr.name])
      newErrors[attr.name] = err
      if (err) {
        flag = true
      }
    })
    setErrors(newErrors)
    return flag
  }

  const saveGenricForm = () => {
    dispatch(claimActions.saveGenericAttributes({
      payload: values,
      claim_id: id,
      form: formName,
      source: 'direct'
    }))
  }

  const onSubmitHandler = (e) => {
    e.preventDefault()
    const err = validateFields()
    if (err) return
    saveGenricForm()
  }

  return (
    <ClaimServiceCenterFormContainer>
      {
        noBrandSpecializationModal
          ? (
            <CustomModal
              leftButton
              leftButtonText={<FormattedMessage id={LANG_STRINGS.close} />}
              headerText={<FormattedMessage id={LANG_STRINGS.information} />}
              visible={noBrandSpecializationModal}
              closeOnShadowDisabled
              closeModal={() => setNoBrandSpecialization(false)}
              onLeftButtonClick={() => setNoBrandSpecialization(false)}
              markupText={
                <NoBrandSpecializationModalText>
                  <div>
                    <img src={InformationFilled} width={40} height={40} />
                  </div>
                  <div>
                    <FormattedMessage id={LANG_STRINGS.noBrandFoundCopyright} />
                  </div>
                  <div>
                    <b>
                      <FormattedMessage id={LANG_STRINGS.customerReachOut} />
                    </b>
                  </div>
                </NoBrandSpecializationModalText>
              }
            />
          )
          : null
      }
      { isBrandOptionExist
        ? <Form>
          <Title>
            <FormattedMessage id={LANG_STRINGS.brandLabel} />
          </Title>
          <Flex>
            {renderInput(attributes.find(({ name }) => name === brandConst))}
          </Flex>
        </Form>
        : null
      }
      <Form>
        <Title>
          <FormattedMessage id={LANG_STRINGS.serviceCenterAreaLabel} />
        </Title>
        <Flex>
          {renderInput(attributes.find(({ name }) => name === provinceConst))}
          {renderInput(attributes.find(({ name }) => name === cityConst))}
          {renderInput(attributes.find(({ name }) => name === postalCodeConst))}
        </Flex>
      </Form>
      <Form>
        <Title>
          <FormattedMessage id={LANG_STRINGS.enterServiceCenterName} />
        </Title>
        <Flex>
          {renderInput(attributes.find(({ name }) => name === serviceCenterConst))}
          {renderInput(attributes.find(({ name }) => name === serviceBranchCenterConst))}
        </Flex>
      </Form>
      {
        provinceErrorMessage
          ? <RejectRemarksContainer status='invalid'>
            <img src={AlertRedIcon} alt='alert' width={24} height={24} />
            <RejectRemarksText status='invalid'>
              <FormattedMessage
                id={provinceErrorMessage}
                defaultMessage={provinceErrorMessage}
              />
            </RejectRemarksText>
          </RejectRemarksContainer>
          : null
      }
      <SubmitButton
        onClick={onSubmitHandler}
      >
        {
          saveFormLoading
            ? <Loader />
            : null
        }
        <FormattedMessage id={LANG_STRINGS.submit} />
      </SubmitButton>
    </ClaimServiceCenterFormContainer>
  )
}

export default AddressFormWrapper
