/* eslint-disable react/jsx-filename-extension */
import React, { useState, useCallback } from 'react'
import { useIntl } from 'react-intl'
import moment from 'moment'
import {
  AlreadySaved,
  AttrTextContainer,
  ClaimFormValuesContainer,
  DisclaimerContainer,
  DisclaimerLabel,
  IconImage,
  IconImageContainer,
  ImageContainer,
  ImageShowCase,
  Label,
  PdfPreviewBox,
  Title,
  Value,
} from './claimGenricFormValues.style'
import {
  CLAIMFORMICONS,
  FORMFIELDTYPES,
  STATUS_GROUP_INITIATED,
} from '../../constants'
import { LANG_STRINGS } from '../../constants/lang'
import CustomCheckBox from '../CustomCheckBox/CustomCheckBox'
import { COLORS } from '../../constants/colors'
import IntlMessages from '../utility/intlMessages'
import DisclaimerModal from '../DisclaimerModal'
import { SketchImage } from '../CarSketch/CarSketch.style'
import { getFileType } from '../../helpers/getFileType'
import FilePreview from '../FilePreview'
import { Document, Page } from 'react-pdf'
import { getClaimAmountWithCurrency } from '../../helpers/getClaimAmountWithCurrency'

const getFileUrl = (item) => {
  if (typeof item === 'object' && item) return item.url || item.get_signed_url || ''
  return item || ''
}

function ClaimGenricFormValues({
  claimStatus,
  formTitle,
  formName: _formName,
  formData,
  packageCountry,
}) {
  const intl = useIntl()
  const [showDisclaimerModal, setShowDisclaimerModal] = useState(false)
  const [previewFiles, setPreviewFiles] = useState(null)
  const [previewIndex, setPreviewIndex] = useState(0)

  const handlePreview = useCallback((urls, idx) => {
    setPreviewFiles(urls.map((u) => ({ url: getFileUrl(u) })))
    setPreviewIndex(idx)
  }, [])

  const closePreview = useCallback(() => {
    setPreviewFiles(null)
  }, [])

  const renderValue = (attr) => {
    const { type, label, value, options = [], name } = attr
    const icon = CLAIMFORMICONS[type] || CLAIMFORMICONS.default
    switch (type) {
      case FORMFIELDTYPES.DATE:
        return (
          <AttrTextContainer>
            <IconImageContainer>
              <IconImage src={icon} />
            </IconImageContainer>
            <div>
              <Label>
                {intl.formatMessage({
                  id: label,
                })}
              </Label>
              <Value>
                {value && moment(value).isValid()
                  ? intl.formatDate(moment(value), {
                      day: 'numeric',
                      month: 'short',
                      year: 'numeric',
                    })
                  : null}
              </Value>
            </div>
          </AttrTextContainer>
        )
      case FORMFIELDTYPES.choices: {
        const found = options.find(([opValue]) => opValue === value)
        return (
          <AttrTextContainer>
            <IconImageContainer>
              <IconImage src={icon} />
            </IconImageContainer>
            <div>
              <Label>
                <IntlMessages id={label} />
              </Label>
              <Value>
                {intl.formatMessage({
                  id: (found && found[1]) || ' ',
                })}
              </Value>
            </div>
          </AttrTextContainer>
        )
      }
      case FORMFIELDTYPES.CHECKBOX:
        return (
          <DisclaimerContainer>
            <CustomCheckBox
              width="20px"
              height="20px"
              checkedPosition={{
                height: 14,
                width: 8,
                left: 4,
                bottom: 3,
                borderRadius: 2,
              }}
              disabled
              checked={value}
              paddingLeft="12px"
              checkedBoxTopAlignment="5px"
              unCheckedBorderColor={COLORS.monoChromeGrey}
              borderColor={COLORS.white}
              checkedColor={COLORS.tapPartnerBlue}
            />
            <DisclaimerLabel>
              <IntlMessages id={label} />
            </DisclaimerLabel>
          </DisclaimerContainer>
        )
      case FORMFIELDTYPES.DISCLAIMER:
        if (name === 'disclaimer_aus') {
          return (
            <DisclaimerContainer>
              <CustomCheckBox
                width="20px"
                height="20px"
                checkedPosition={{
                  height: 14,
                  width: 8,
                  left: 4,
                  bottom: 3,
                  borderRadius: 2,
                }}
                disabled
                checked={value}
                paddingLeft="12px"
                checkedBoxTopAlignment="5px"
                unCheckedBorderColor={COLORS.monoChromeGrey}
                borderColor={COLORS.white}
                checkedColor={COLORS.tapPartnerBlue}
              />
              <DisclaimerLabel>
                <IntlMessages
                  id={LANG_STRINGS.disclaimerText}
                  values={{
                    highlight: (chunks) => (
                      <span
                        onClick={() => setShowDisclaimerModal(true)}
                        style={{
                          textDecoration: 'underline',
                          cursor: 'pointer',
                        }}
                      >
                        {chunks}
                      </span>
                    ),
                  }}
                />
              </DisclaimerLabel>
              <DisclaimerModal
                isOpen={showDisclaimerModal}
                onClose={() => setShowDisclaimerModal(false)}
              />
            </DisclaimerContainer>
          )
        }
        return (
          <DisclaimerContainer>
            <CustomCheckBox
              width="20px"
              height="20px"
              checkedPosition={{
                height: 14,
                width: 8,
                left: 4,
                bottom: 3,
                borderRadius: 2,
              }}
              disabled
              checked={value}
              paddingLeft="12px"
              checkedBoxTopAlignment="5px"
              unCheckedBorderColor={COLORS.monoChromeGrey}
              borderColor={COLORS.white}
              checkedColor={COLORS.tapPartnerBlue}
            />
            <DisclaimerLabel>
              <IntlMessages id={label} />
            </DisclaimerLabel>
          </DisclaimerContainer>
        )
      case FORMFIELDTYPES.BOOLEAN: {
        const displayValue = intl.formatMessage({
          id: value ? LANG_STRINGS.yes : LANG_STRINGS.no,
        })

        return (
          <AttrTextContainer>
            <IconImageContainer>
              <IconImage src={icon} />
            </IconImageContainer>
            <div>
              <Label>
                {intl.formatMessage({
                  id: label,
                })}
              </Label>
              <Value>{displayValue}</Value>
            </div>
          </AttrTextContainer>
        )
      }
      case 'image':
        return (
          <AttrTextContainer flexDirection="column">
            <Label>
              {intl.formatMessage({
                id: label,
              })}
            </Label>
            {value && (Array.isArray(value) ? value.length : getFileUrl(value)) ? (
              <ImageContainer>
                {Array.isArray(value) ? (
                  value.map((item, idx) => {
                    const fileUrl = getFileUrl(item)
                    const isPdf = getFileType(fileUrl) === 'application/pdf'
                    if (isPdf) {
                      return (
                        <PdfPreviewBox
                          key={fileUrl}
                          onClick={() => handlePreview(value, idx)}
                        >
                          <Document file={{ url: fileUrl }}>
                            <Page pageNumber={1} width={280} renderTextLayer={false} renderAnnotationLayer={false} />
                          </Document>
                        </PdfPreviewBox>
                      )
                    }
                    return (
                      <ImageShowCase
                        key={fileUrl}
                        src={fileUrl}
                        onClick={() => handlePreview(value, idx)}
                        style={{ cursor: 'pointer' }}
                      />
                    )
                  })
                ) : (
                  (() => {
                    const fileUrl = getFileUrl(value)
                    const isPdf = getFileType(fileUrl) === 'application/pdf'
                    return isPdf ? (
                      <PdfPreviewBox onClick={() => handlePreview([value], 0)}>
                        <Document file={{ url: fileUrl }}>
                          <Page pageNumber={1} width={280} renderTextLayer={false} renderAnnotationLayer={false} />
                        </Document>
                      </PdfPreviewBox>
                    ) : (
                      <ImageShowCase
                        src={fileUrl}
                        onClick={() => handlePreview([value], 0)}
                        style={{ cursor: 'pointer' }}
                      />
                    )
                  })()
                )}
              </ImageContainer>
            ) : null}
          </AttrTextContainer>
        )
      case FORMFIELDTYPES.SKETCH:
        return (
          <AttrTextContainer flexDirection="column">
            <Label>
              {intl.formatMessage({
                id: label,
              })}
            </Label>
            {value && value.length ? (
              <SketchImage src={value} alt="car sketch" />
            ) : null}
          </AttrTextContainer>
        )
      case FORMFIELDTYPES.STRING:
        if (name === 'claim_amount') {
          return (
            <AttrTextContainer>
              <IconImageContainer>
                <IconImage src={icon} />
              </IconImageContainer>
              <div>
                <Label>
                  {intl.formatMessage({
                    id: label,
                  })}
                </Label>
                <Value>
                  {getClaimAmountWithCurrency(value, packageCountry)}
                </Value>
              </div>
            </AttrTextContainer>
          )
        }
      // fallthrough
      // falls through
      default:
        return (
          <AttrTextContainer>
            <IconImageContainer>
              <IconImage src={icon} />
            </IconImageContainer>
            <div>
              <Label>
                {intl.formatMessage({
                  id: label,
                })}
              </Label>
              <Value>{value}</Value>
            </div>
          </AttrTextContainer>
        )
    }
  }

  return (
    <>
    <ClaimFormValuesContainer>
      <Title>
        <IntlMessages id={formTitle} />
      </Title>
      {(formData || []).map((attr) => (
        <React.Fragment key={attr.name}>{renderValue(attr)}</React.Fragment>
      ))}
      {[STATUS_GROUP_INITIATED].includes(claimStatus) ? (
        <AlreadySaved>
          <IntlMessages id={LANG_STRINGS.alreadySaved} />
        </AlreadySaved>
      ) : null}
    </ClaimFormValuesContainer>
    {previewFiles && (
      <FilePreview
        files={previewFiles}
        initialIndex={previewIndex}
        onClose={closePreview}
      />
    )}
    </>
  )
}

export default ClaimGenricFormValues
