import { useState } from 'react'
import { useDispatch } from 'react-redux'

import claimActions from '../../../redux/claim/actions'
import ClaimBankDetailsV2 from '../../../components/ClaimBankDetailsV2'
import ClaimBankFormValues from '../../../components/ClaimBankFormValues'
import Radio from '../../../components/Radio'
import { bankDetailFormTitleV2, goPayWalletFormName } from '../../../constants'
import GoPayWallet from './goPayWallet'
import { Form, PaymentFormContainer } from './paymentForm.style'
import IntlMessages from '../../../components/utility/intlMessages'

function PaymentForms ({
  claimData,
  bankList
}) {
  const { payment_forms: forms } = claimData
  const dispatch = useDispatch()
  const [choosenPaymentMode, setChoosenPaymentMode] = useState()
  if (!forms) return null
  if (!forms.length) return null

  const bankFormValid = forms.find(({ is_valid: isValid }) => isValid)

  if (bankFormValid) {
    return (
      <ClaimBankFormValues
        bankList={bankList}
        claimData={claimData}
        bankDeatilForm={bankFormValid}
      />
    )
  }

  const handlePaymentFormSubmit = (body) => {
    dispatch(claimActions.savePaymentForm(body))
  }

  const onChangeHandler = ({ name }) => {
    setChoosenPaymentMode(name)
  }

  return (
    <PaymentFormContainer >
      {
        forms.map((form) => {
          const { name, title } = form
          const renderBankForm = () => {
            if (!choosenPaymentMode || choosenPaymentMode !== name) return <IntlMessages id={title} />
            if (choosenPaymentMode === goPayWalletFormName) {
              return <GoPayWallet
                form={form}
                claimData={claimData}
                handleSubmit={handlePaymentFormSubmit}
              />
            }
            if (choosenPaymentMode === bankDetailFormTitleV2) {
              return <ClaimBankDetailsV2
                claimData={claimData}
                bankDetailForm={form}
                handleSubmit={handlePaymentFormSubmit}
              />
            }
            return null
          }
          return (
            <Form>
              <Radio onChange={(e) => onChangeHandler({ e, name })} />
              {renderBankForm()}
            </Form>
          )
        })
      }
    </PaymentFormContainer >
  )
}

export default PaymentForms
