import { useEffect, useState } from 'react'
import { injectIntl } from 'react-intl'
import moment from 'moment'
import momentTimezone from 'moment-timezone'
import Select from '../SelectV2'

import {
  FlexContainer
} from './DatePicker.style'

function DatePicker (props) {
  const { intl, endingDate, startingDate, value, handleDateChange, name, disabled, changeErrorStatus, error } = props

  const { formatMessage } = intl

  const [date, setDate] = useState(value ? moment(value).local().date() : undefined)
  const [month, setMonth] = useState(value ? moment(value).local().month() + 1 : undefined)
  const [year, setYear] = useState(value ? moment(value).local().year() : moment().year())

  const errorCheckHandler = ({ date, month, year }) => {
    if (date && month && year) {
      let errorMessage = ''
      const momentObject = momentTimezone.tz(`${date}-${month}-${year}`, 'DD-MM-YYYY', 'UTC').startOf('day')
      const dateObject = momentObject.toDate()

      if (!startingDate && !endingDate) {
        let endingDay = moment().endOf().date()
        let endingMonth = moment().endOf().month() + 1
        let endingYear = moment().endOf().year()

        let flag = true

        if (year > endingYear) {
          flag = false
        }

        if (year === endingYear && month > endingMonth) {
          flag = false
        }

        if (year === endingYear && month === endingMonth && date > endingDay) {
          flag = false
        }

        if (flag) {
          handleDateChange(dateObject, name)
          return
        }
        errorMessage = 'Tanggal harus kurang dari {endingDate}'
      }
      if (startingDate && !endingDate) {
        let endingDay = moment().endOf().date()
        let endingMonth = moment().endOf().month() + 1
        let endingYear = moment().endOf().year()

        let startingDay = moment(startingDate).startOf().date()
        let startingMonth = moment(startingDate).startOf().month() + 1
        let startingYear = moment(startingDate).startOf().year()

        let flag = true

        if (year > endingYear) {
          flag = false
        }

        if (year === endingYear && month > endingMonth) {
          flag = false
        }

        if (year === endingYear && month === endingMonth && date > endingDay) {
          flag = false
        }

        if (year < startingYear) {
          flag = false
        }

        if (year === startingYear && month < startingMonth) {
          flag = false
        }

        if (year === startingYear && month === startingMonth && date < startingDay) {
          flag = false
        }

        if (flag) {
          handleDateChange(dateObject, name)
          return
        }
        errorMessage = 'Tanggal harus antara {startingDate} dan {endingDate}'
      }
      if (!startingDate && endingDate) {
        let endingDay = moment(endingDate).endOf().date()
        let endingMonth = moment(endingDate).endOf().month() + 1
        let endingYear = moment(endingDate).endOf().year()

        let flag = true

        if (year > endingYear) {
          flag = false
        }

        if (year === endingYear && month > endingMonth) {
          flag = false
        }

        if (year === endingYear && month === endingMonth && date > endingDay) {
          flag = false
        }

        if (flag) {
          handleDateChange(dateObject, name)
          return
        }
        errorMessage = 'Tanggal harus kurang dari {endingDate}'
      }
      if (startingDate && endingDate) {
        let endingDay = moment(endingDate).endOf().date()
        let endingMonth = moment(endingDate).endOf().month() + 1
        let endingYear = moment(endingDate).endOf().year()

        let startingDay = moment(startingDate).startOf().date()
        let startingMonth = moment(startingDate).startOf().month() + 1
        let startingYear = moment(startingDate).startOf().year()

        let flag = true

        if (year > endingYear) {
          flag = false
        }

        if (year === endingYear && month > endingMonth) {
          flag = false
        }

        if (year === endingYear && month === endingMonth && date > endingDay) {
          flag = false
        }

        if (year < startingYear) {
          flag = false
        }

        if (year === startingYear && month < startingMonth) {
          flag = false
        }

        if (year === startingYear && month === startingMonth && date < startingDay) {
          flag = false
        }

        if (flag) {
          handleDateChange(dateObject, name)
          return
        }
        errorMessage = 'Tanggal harus antara {startingDate} dan {endingDate}'
      }
      if (errorMessage) {
        const errorText = intl.formatMessage({
          id: errorMessage,
          description: errorMessage,
          defaultMessage: errorMessage
        }, {
          startingDate: startingDate ? moment(startingDate).format('DD-MM-YY') : moment().format('DD-MM-YY'),
          endingDate: endingDate ? moment(endingDate).format('DD-MM-YY') : moment().format('DD-MM-YY')
        })
        changeErrorStatus({ name, error: errorText })
      }
    }
  }

  useEffect(() => {
    const selectedMonth = monthOptions().find(({ value }) => month === value)

    const { days = 31 } = selectedMonth || {}
    if (days < date) {
      setDate(days)
    }
  }, [month])

  const dateOptions = () => {
    let noOfDays = 31
    const startingMoment = startingDate && moment(startingDate)
    const endingMoment = endingDate && moment(endingDate)

    const startingMonth = startingMoment && startingMoment.month() + 1
    const endingMonth = endingMoment && endingMoment.month() + 1
    const startingYear = startingMoment && startingMoment.year()
    const endingYear = endingMoment && endingMoment.year()

    const selectedMonth = monthOptions().find(({ value }) => month === value)
    const { days = 31 } = selectedMonth || {}

    const selectedDates = new Array(days || noOfDays).fill(null).map((_, index) => ({
      value: index + 1,
      displayName: index + 1
    }))

    if (startingMoment && endingMoment) {
      return selectedDates.filter(({ value }) => {
        const isAfterStartingDate =
          (year > startingYear || (year === startingYear && month > startingMonth)) ||
          (year === startingYear && month === startingMonth && value >= startingMoment.date())

        const isBeforeEndingDate =
          (year < endingYear || (year === endingYear && month < endingMonth)) ||
          (year === endingYear && month === endingMonth && value <= endingMoment.date())

        return isAfterStartingDate && isBeforeEndingDate
      })
    }

    return selectedDates
  }

  const monthOptions = () => {
    const startingMonth = startingDate && moment(startingDate).month()
    const endingMonth = endingDate && moment(endingDate).month()

    const monthInfo = [
      {
        'id': 1,
        'displayName': 'Januari',
        'days': 31,
        'value': 1
      },
      {
        'id': 2,
        'displayName': 'Februari',
        'days': year % 4 ? 28 : 29,
        'value': 2
      },
      {
        'id': 3,
        'displayName': 'Maret',
        'days': 31,
        'value': 3
      },
      {
        'id': 4,
        'displayName': 'April',
        'days': 30,
        'value': 4
      },
      {
        'id': 5,
        'displayName': 'Mei',
        'days': 31,
        'value': 5
      },
      {
        'id': 6,
        'displayName': 'Juni',
        'days': 30,
        'value': 6
      },
      {
        'id': 7,
        'displayName': 'Juli',
        'days': 31,
        'value': 7
      },
      {
        'id': 8,
        'displayName': 'Agustus',
        'days': 31,
        'value': 8
      },
      {
        'id': 9,
        'displayName': 'September',
        'days': 30,
        'value': 9
      },
      {
        'id': 10,
        'displayName': 'Oktober',
        'days': 31,
        'value': 10
      },
      {
        'id': 11,
        'displayName': 'November',
        'days': 30,
        'value': 11
      },
      {
        'id': 12,
        'displayName': 'Desember',
        'days': 31,
        'value': 12
      }
    ]
    const startingYear = moment(startingDate).year()
    const endingYear = moment(endingDate).year()
    if (Math.abs(startingYear - endingYear) < 1) {
      if (startingMonth <= endingMonth) {
        const a = monthInfo.filter((info) => {
          const { id } = info
          if (id >= startingMonth + 1 && id <= endingMonth + 1) {
            return true
          }
          return false
        })
        return a
      } else if (startingMonth > endingMonth) {
        const a = monthInfo.filter((info) => {
          const { id } = info
          if (id >= startingMonth + 1) {
            return true
          }
          if (id <= endingMonth + 1) {
            return true
          }
          return false
        })
        return a
      }
    }
    return monthInfo
  }

  const yearOptions = () => {
    if (startingDate && endingDate) {
      const startingYear = moment(startingDate).year()
      const endingYear = moment(endingDate).year()

      if (startingYear === endingYear) {
        return ([
          {
            'id': startingYear,
            'displayName': startingYear,
            'value': startingYear
          }
        ])
      }
      let array = []
      for (let i = startingYear; i <= endingYear; i++) {
        array = [...array, i]
      }

      return array.map((year) => ({
        id: year,
        displayName: year,
        value: year
      }))
    }

    return new Array(200).fill(null).map((_, index) => ({
      value: index + 1900,
      displayName: index + 1900
    }))
  }

  return (
    <FlexContainer>
      <Select
        value={month}
        error={error}
        disabled={disabled}
        options={monthOptions()}
        placeholder={formatMessage({
          id: 'Bulan',
          defaultMessage: 'Bulan'
        })}
        onSelect={(value) => {
          errorCheckHandler({ month: value, year, date })
          setMonth(value)
        }}
      />

      <Select
        value={date}
        error={error}
        disabled={disabled}
        options={dateOptions()}
        placeholder={formatMessage({
          id: 'Tanggal',
          defaultMessage: 'Tanggal'
        })}
        onSelect={(value) => {
          errorCheckHandler({ date: value, year, month })
          setDate(value)
        }
        }
      />

      <Select
        value={year}
        error={error}
        disabled={disabled}
        options={yearOptions()}
        placeholder={formatMessage({
          id: 'Tahun',
          defaultMessage: 'Tuhan'
        })}
        onSelect={(value) => {
          errorCheckHandler({ year: value, date, month })
          setYear(value)
        }}
      />

    </FlexContainer>
  )
}

export default injectIntl(DatePicker)
