import get from 'lodash/get'
import IntlMessages from '../../../components/utility/intlMessages'
import { LANG_STRINGS } from '../../../constants/lang'
import {
  CartIcon,
  LikedIcon,
  PackageIcon,
  PolicyId,
  SentIcon,
  TagIcon
} from '../../../image'
import {
  BenefitConatiner,
  BenefitName,
  BenefitTitle,
  ClaimDetailContainer,
  ClaimDetailTitle,
  Flex,
  Icon,
  IconImage,
  MainDetailContainer,
  StatusContainer,
  StatusName,
  StatusTitle,
  Title,
  Value
} from './claimMainDetail.style'

function ClaimMainDetail ({
  claimData
}) {
  const {
    benefit_name: benefitName
  } = claimData
  const claimStatus = get(claimData, 'status_group', '')
  const statusDescription = get(claimData, 'status.display_name', '')
  const statusRemarks = get(claimData, claimStatus !== 'rejected' ? '' : 'reject_remarks', '')
  const claimCreatedAt = get(claimData, 'created_at', '')
  const productName = get(claimData, 'product_key', '')
  const packageName = get(claimData, 'package_name', '')
  const category = get(claimData, 'category', '')
  const partnerName = get(claimData, 'partner_id', '')
  const policyId = get(claimData, 'policy_number', '')
  const applicationNumber = get(claimData, 'application_no', '')
  const policy_prefix = get(claimData, 'policy_details.Request.policy_prefix','')

  const mainDetails = [
    {
      icon: SentIcon,
      title: LANG_STRINGS.claimInitiated,
      value: claimCreatedAt
    },
    {
      icon: CartIcon,
      title: LANG_STRINGS.product,
      value: productName
    },
    {
      icon: PackageIcon,
      title: LANG_STRINGS.paketLabel,
      value: packageName
    },
    {
      icon: TagIcon,
      title: LANG_STRINGS.categoryLabel,
      value: category
    },
    {
      icon: LikedIcon,
      title: LANG_STRINGS.partnerLabel,
      value: partnerName
    },
    {
      icon: PolicyId,
      title: LANG_STRINGS.policyIdLabel,
      value: policy_prefix ? `${policy_prefix}${policyId}` : policyId || applicationNumber
    }
  ]
  return (
    <ClaimDetailContainer>
      <ClaimDetailTitle>
        <IntlMessages id={LANG_STRINGS.claimDetail} />
      </ClaimDetailTitle>

      <BenefitConatiner>
        <BenefitTitle>
          <IntlMessages id={LANG_STRINGS.benefitTitle} />
        </BenefitTitle>
        <BenefitName>
          <IntlMessages id={benefitName} />
        </BenefitName>
      </BenefitConatiner>

      <StatusContainer status={claimStatus}>
        <StatusTitle>
          <IntlMessages id={LANG_STRINGS.statusClaimTitle} />
        </StatusTitle>
        <StatusName>
          <IntlMessages id={statusDescription} />
        </StatusName>
        <StatusName>
          <IntlMessages id={statusRemarks} />
        </StatusName>
      </StatusContainer>

      <MainDetailContainer>
        {
          mainDetails.map(({ title, value, icon }) => {
            return (
              <Flex key={title}>
                <Icon>
                  <IconImage src={icon} width={24} height={24} />
                </Icon>
                <div>
                  <Title>
                    <IntlMessages id={title} />
                  </Title>
                  <Value><IntlMessages id={value} /></Value>
                </div>
              </Flex>
            )
          })
        }
      </MainDetailContainer>

    </ClaimDetailContainer>
  )
}

export default ClaimMainDetail
