import React from 'react'
import ReactDOM from 'react-dom'
import {
  Overlay,
  Sheet,
  Header,
  HeaderCloseBtn,
  Options,
  OptionCard,
  OptionLabel,
} from './uploadSourceModal.style'

const CameraIcon = () => (
  <svg width='36' height='36' viewBox='0 0 24 24' fill='none'>
    <path
      d='M23 19a2 2 0 01-2 2H3a2 2 0 01-2-2V8a2 2 0 012-2h4l2-3h6l2 3h4a2 2 0 012 2v11z'
      stroke='#333'
      strokeWidth='1.5'
      strokeLinecap='round'
      strokeLinejoin='round'
    />
    <circle cx='12' cy='13' r='4' stroke='#333' strokeWidth='1.5' />
  </svg>
)

const GalleryIcon = () => (
  <svg width='36' height='36' viewBox='0 0 24 24' fill='none'>
    <rect
      x='3'
      y='3'
      width='18'
      height='18'
      rx='2'
      stroke='#333'
      strokeWidth='1.5'
    />
    <circle cx='8.5' cy='8.5' r='1.5' fill='#333' />
    <path
      d='M21 15l-5-5L5 21'
      stroke='#333'
      strokeWidth='1.5'
      strokeLinecap='round'
      strokeLinejoin='round'
    />
  </svg>
)

const UploadSourceModal = ({ onSelectCamera, onSelectGallery, onClose, onlyCamera }) =>
  ReactDOM.createPortal(
    <>
      <Overlay onClick={onClose} />
      <Sheet>
        <Header>
          Upload Photo
          <HeaderCloseBtn onClick={onClose}>✕</HeaderCloseBtn>
        </Header>
        <Options>
          <OptionCard
            onClick={(e) => {
              e.stopPropagation()
              onSelectCamera()
            }}
          >
            <CameraIcon />
            <OptionLabel>Camera</OptionLabel>
          </OptionCard>
          {!onlyCamera && (
            <OptionCard
              onClick={(e) => {
                e.stopPropagation()
                onSelectGallery()
              }}
            >
              <GalleryIcon />
              <OptionLabel>Gallery</OptionLabel>
            </OptionCard>
          )}
        </Options>
      </Sheet>
    </>,
    document.getElementById('modal-root') || document.body,
  )

export default UploadSourceModal
