import ClaimGenricForm from '../../../components/ClaimGenricForm'
import ClaimGenricFormValues from '../../../components/ClaimGenricFormValues/claimGenricFormValues'
import IntlMessages from '../../../components/utility/intlMessages'
import {
  serviceCenterFormTitle,
  workshopSelectionFormTitle,
  bankDeatilsFormTitle,
  bankDetailFormTitleV2,
  STATUS_GROUP_INITIATED,
  STATUS_GROUP_DOC_REPROCESS,
  STATUS_GROUP_REJECTED,
  STATUS_GROUP_SETTLED,
  STATUS_GROUP_SALVAGE_PENDING,
  STATUS_GROUP_DOCUMENT_PENDING
} from '../../../constants'
import ClaimServiceCenterForm from '../../../components/ClaimServiceCenterForm'
import ClaimBengkelWorkshopForm from '../../../components/ClaimBengkelWorkshopForm'
import { ClaimFormContainer, Wrapper, FormDescription } from './claimForm.style'
import ClaimBankDetailsV2 from '../../../components/ClaimBankDetailsV2'
import ClaimBankFormValues from '../../../components/ClaimBankFormValues'

function ClaimForms ({
  claimData = {},
  bankList = []
}) {
  const { forms = [], claim_id: claimId, status_group: claimStatus, package_country: packageCountry } = claimData
  const isSettledOrRejected = [STATUS_GROUP_REJECTED, STATUS_GROUP_SETTLED].includes(claimStatus)
  const showSubmitButton = [
    STATUS_GROUP_INITIATED,
    STATUS_GROUP_DOC_REPROCESS,
    STATUS_GROUP_SALVAGE_PENDING,
    STATUS_GROUP_DOCUMENT_PENDING
  ].includes(claimStatus)
  return (
    <Wrapper>
      {
        forms.map((form) => {
          const {
            name,
            attributes,
            is_valid: isValid,
            description,
            is_salvage: isSalvage
          } = form
          const isServicecenterForm = serviceCenterFormTitle === name
          const isBankdetailsForm = [bankDeatilsFormTitle, bankDetailFormTitleV2].includes(name)
          if (isServicecenterForm) {
            return (
              <ClaimServiceCenterForm
                key={name}
                serviceCenterForm={form}
                showSubmitButton={showSubmitButton}
              />
            )
          }
          if (name === workshopSelectionFormTitle) {
            return (
              <ClaimBengkelWorkshopForm
                key={name}
                formName={name}
                claimId={claimId}
                description={description}
                attributes={attributes}
                showSubmitButton={!isValid}
              />
            )
          }
          if (isBankdetailsForm) {
            if (isValid || isSettledOrRejected) {
              return (
                <ClaimBankFormValues
                  key={name}
                  bankList={bankList}
                  bankDeatilForm={form}
                />
              )
            }
            return (
              <ClaimBankDetailsV2
                key={name}
                bankList={bankList}
                claimData={claimData}
                bankDetailForm={form}
              />
            )
          }
          if (isValid || isSettledOrRejected) {
            return (
              <ClaimGenricFormValues
                key={name}
                formTitle={description}
                formName={name}
                claimId={claimId}
                formData={attributes}
                claimStatus={claimStatus}
                packageCountry={packageCountry}
              />
            )
          }
          return (
            <ClaimFormContainer key={name}>
              <FormDescription>
                <IntlMessages id={form.description} />
              </FormDescription>
              <ClaimGenricForm
                form={form}
                isSalvage={isSalvage}
                formName={name}
                claimId={claimId}
                formData={attributes}
                claimStatus={claimStatus}
                showSubmitButton={showSubmitButton}
              />
            </ClaimFormContainer>
          )
        })
      }
    </Wrapper>

  )
}

export default ClaimForms
