import React from 'react'
import { useIntl } from 'react-intl'
import PropTypes from 'prop-types'

import {
  Wrapper,
  TextInputContainer,
  TextInputItem,
  TextInputItemContainer,
  LabelTitle
} from './elements'

const TextInput = (props) => {
  const { placeholder, width, onChange = () => { }, onBlur, value, error, title = '' } = props
  const intl = useIntl()
  return (
    <Wrapper>
      <TextInputContainer error={error}>
        <LabelTitle>
          {title}
        </LabelTitle>
        <TextInputItemContainer width={width}>
          <TextInputItem
            value={value}
            id={`${props.name}~input`}
            data-attr-slug={`${props.name}~${props.form?.name}~input`}
            disabled={props.disabled}
            pattern={props.pattern}
            type={props.type}
            onBlur={onBlur}
            inputMode={props.inputMode}
            onChange={(event) => onChange({ value: event.target.value, name: props.name })}
            placeholder={intl.formatMessage({
              id: placeholder || ' ',
              defaultMessage: placeholder || ' '
            })}
          />
        </TextInputItemContainer>
      </TextInputContainer>
    </Wrapper>

  )
}

TextInput.propTypes = {
  label: PropTypes.string.isRequired,
  name: PropTypes.string.isRequired
}

TextInput.defaultProps = {
}

export default TextInput
