import { useEffect, useState } from 'react'
import IntlMessages from '../utility/intlMessages'
import { LANG_STRINGS } from '../../constants/lang'
import {
  AccNumber,
  AttributeContainer,
  BankAccRadioDiv,
  BankAccountDiv,
  BankAccountDiv1,
  BankChoiceContainer,
  BankDeatilsDiv,
  ClaimDetailContainer,
  ClaimDetailTitle,
  ErrorText,
  SaveButton
} from './index.style'
import get from 'lodash/get'
import claimActions from '../../redux/claim/actions'
import { useDispatch, useSelector } from 'react-redux'
import SliderSwitch from '../SliderSwitch'
import Radio from '../Radio'
import { FormattedMessage, useIntl } from 'react-intl'
import TextInput from '../Textinput'
import {
  FORMFIELDTYPES,
  STATUS_GROUP_DOC_REPROCESS,
  STATUS_GROUP_INITIATED
} from '../../constants'
import Loader from '../Loader'
import { useRemoveErrorActionsHelper, useRemoveLoadingActionsHelper } from '../../helpers/utility'
import SearchDropdown from '../SearchDropdown'

export const claimBankMap = (bank) => ([
  {
    title: 'Nama lengkap nasabah',
    value: bank.holder_name,
    fontWeight: 800
  },
  {
    title: 'Nomor Rekening',
    value: bank.account_no
  },
  {
    title: 'Nama Bank',
    value: bank.bank_code
  }
])

function ClaimBankDetailsV2 ({ claimData, bankDetailForm = {}, handleSubmit }) {
  const { attributes, name: formName } = bankDetailForm

  const dispatch = useDispatch()
  const intl = useIntl()
  const claimBankDetails = useSelector(state => state.User.details)
  const bankAccounts = get(claimBankDetails, 'bank_accounts', '')
  const formLoading = useSelector(state => state.Claim.formLoadingStates[formName])
  const verifyBankFormLoading = useRemoveLoadingActionsHelper(claimActions.VERIFY_BANK_ACCOUNT_FORMS_REQUEST)
  const verifyBankFormError = useRemoveErrorActionsHelper(claimActions.VERIFY_BANK_ACCOUNT_FORMS_REQUEST)
  const { claim_no: claimNo, claim_id: claimId, status_group: claimStatus } = claimData
  const [showBankAcc, setShowBankAcc] = useState(!bankAccounts.length)
  const [checkedIndex, setCheckedIndex] = useState(null)
  const [bankDetails, setBankDetails] = useState({})
  const disabled = ![STATUS_GROUP_INITIATED, STATUS_GROUP_DOC_REPROCESS].includes(claimStatus)

  const onChange = (e) => {
    setShowBankAcc(e.target.checked)
  }
  const verifyAccountData = useSelector(state => state.Claim.verifyAccountData)
  const verifyBankAccountFormStatus = useSelector(state => state.Claim.verifyBankAccountFormStatus)

  useEffect(() => {
    return () => {
      dispatch(claimActions.resetReduxState([
        'verifyAccountData',
        'verifyBankAccountFormStatus'
      ]))
    }
  }, [
    claimId
  ])

  useEffect(() => {
    if (verifyBankAccountFormStatus === 'success') {
      setBankDetails((details) => ({
        ...details,
        'account_holder_name': verifyAccountData.account_holder_name
      }))
    }
  }, [
    verifyAccountData,
    verifyBankAccountFormStatus
  ])

  const hadleClick = () => {
    if (![STATUS_GROUP_INITIATED, STATUS_GROUP_DOC_REPROCESS].includes(claimStatus)) return
    if (checkedIndex === null && !Object.keys(bankDetails).length) return
    const body = {
      claim_id: claimId,
      form: formName,
      payload: {
        account_holder_name: bankDetails.account_holder_name || (bankAccounts?.[checkedIndex]?.holder_name),
        account_number: bankDetails.account_number || bankAccounts?.[checkedIndex]?.account_no,
        bank_code: Number(bankDetails.bank_name) || Number(bankAccounts?.[checkedIndex]?.bank_code),
        bank_name: Number(bankDetails.bank_name) || Number(bankAccounts?.[checkedIndex]?.bank_code),
        claim_no: claimNo,
        source: 'direct'
      }
    }
    if (handleSubmit) {
      handleSubmit(body)
      return
    }
    dispatch(claimActions.saveGenericAttributes(body))
  }

  const verifyBankDetails = () => {
    if (![STATUS_GROUP_INITIATED, STATUS_GROUP_DOC_REPROCESS].includes(claimStatus)) return
    if (!Object.keys(bankDetails).length) return
    const payload = {
      account_number: bankDetails.account_number,
      bank_name: bankDetails.bank_name,
      bank_code: bankDetails.bank_name
    }
    dispatch(claimActions.verifyBankAccountForms({ payload }))
  }

  const renderBankDetails = (list, index) => {
    return (
      <BankDeatilsDiv>
        <div>
          {
            list.map((account, index) => (
              <BankAccRadioDiv key={JSON.stringify(account)}>
                <AccNumber fontWeight={account.fontWeight}> {account.value} </AccNumber>
              </BankAccRadioDiv>
            ))
          }
        </div>
        <Radio disabled={disabled} onChange={() => setCheckedIndex(index)} checked={checkedIndex === index} />
      </BankDeatilsDiv>
    )
  }

  const onChangeHandler = ({ value, name }) => {
    setBankDetails(payload => ({
      ...payload,
      [name]: value
    }))
  }

  return (
    <ClaimDetailContainer>
      <ClaimDetailTitle>
        <IntlMessages id={LANG_STRINGS.bankAccount} />
      </ClaimDetailTitle>
      <BankAccountDiv >
        <div><IntlMessages id={LANG_STRINGS.selectBankAccount} /></div>
        {
          bankAccounts.length
            ? <BankChoiceContainer>
              <IntlMessages id={LANG_STRINGS.newBankAccount} />
              <SliderSwitch disabled={disabled} className='bank-switch' checked={showBankAcc} onChange={onChange} />
            </BankChoiceContainer>
            : null
        }
      </BankAccountDiv>
      <BankAccountDiv1>
        {!showBankAcc && bankAccounts.length > 0 &&
          bankAccounts.map((item, index) => {
            return renderBankDetails(
              claimBankMap(item), index
            )
          })}
      </BankAccountDiv1>
      {showBankAcc &&
        <AttributeContainer>
          {attributes?.map(({ type, label, placeholder, name, options }) => {
            if (type === FORMFIELDTYPES.choices) {
              if (options && options.length > 0) {
                const op = options.map(([code, name]) => ({ value: code, displayName: name }))
                return (
                  <SearchDropdown
                    key={name}
                    title={intl.formatMessage({ id: label || ' ' })}
                    value={bankDetails[name]}
                    options={op}
                    placeholder={intl.formatMessage({ id: placeholder || label || ' ' })}
                    onSelect={(value) => onChangeHandler({ value, name })}
                  />
                )
              } else {
                // Optionally, render a loading indicator until options are fetched
                return <div key={name}>Loading options...</div>
              }
            }
            return (
              <TextInput
                key={name}
                value={bankDetails[name]}
                name={name}
                title={intl.formatMessage({ id: label || ' ' })}
                onChange={onChangeHandler}
                disabled={name === 'account_holder_name'}
              />
            )
          })}
        </AttributeContainer>

      }
      <ErrorText>
        {verifyBankFormError && <IntlMessages id={verifyBankAccountFormStatus} />}
      </ErrorText>
      {
        disabled
          ? null
          : !showBankAcc
            ? <SaveButton
              onClick={hadleClick}
            >
              {
                formLoading
                  ? <Loader />
                  : null
              }
              <FormattedMessage id={LANG_STRINGS.submit} />
            </SaveButton>
            : !verifyBankFormError && verifyBankAccountFormStatus
              ? <SaveButton
                onClick={hadleClick}
              >
                {
                  formLoading
                    ? <Loader />
                    : null
                }
                <FormattedMessage id={LANG_STRINGS.submit} />
              </SaveButton>
              : <SaveButton
                onClick={verifyBankDetails}
              >
                {
                  verifyBankFormLoading
                    ? <Loader />
                    : null
                }
                <FormattedMessage id={LANG_STRINGS.verify} />
              </SaveButton>
      }
    </ClaimDetailContainer>

  )
}

export default ClaimBankDetailsV2
