import React, { useEffect, useState } from 'react'
import PropTypes from 'prop-types'
import useComponentVisible from '../../hooks/useComponentVisible'
import {
  SearchDropdownWrapper,
  SelectContainer,
  SelectDrop,
  SelectDropInput,
  SelectLabel,
  SelectOptionList,
  SelectOptionContainer,
  SelectOptionListContainer,
  SelectOptionText
} from './elements'

const SearchDropdown = ({ title, value, options, onSelect }) => {
  const { ref, isComponentVisible, setIsComponentVisible } = useComponentVisible(false)
  const [selected, setSelected] = useState(value || null)
  const [iValue, setIValue] = useState('')
  const [filteredOptions, setFilteredOptions] = useState(options)
  const [noOptions, setNoOptions] = useState(false)

  const handleSelect = (selectedOption) => {
    setSelected(selectedOption)
    setIsComponentVisible(false)
    setIValue(selectedOption.displayName)
    onSelect(selectedOption.value)
  }

  const handleChange = (e) => {
    setSelected(null)
    setIValue(e.target.value)
  }

  const handleClick = () => {
    setIsComponentVisible(true)
    if (iValue === '') {
      setFilteredOptions(options)
      setNoOptions(false)
    }
  }

  useEffect(() => {
    if (value) {
      const selectedOption = options.find(opt => opt.value === value)
      setSelected(selectedOption)
      setIValue(selectedOption?.displayName || '')
    }
  }, [value, options])

  useEffect(() => {
    if (!selected) {
      setIsComponentVisible(true)
    }
  }, [iValue, selected])

  useEffect(() => {
    const filtered = options.filter(option =>
      option.displayName.toLowerCase().includes(iValue.toLowerCase())
    )
    setFilteredOptions(iValue === '' ? options : filtered)
    setNoOptions(filtered.length === 0)
  }, [iValue, options])

  return (
    <SearchDropdownWrapper>
      <SelectContainer>
        {title && (
          <SelectLabel>
            {title}
          </SelectLabel>
        )}
        <SelectDrop>
          <SelectDropInput
            type='text'
            onChange={handleChange}
            onClick={handleClick}
            value={iValue || ''}
            ref={ref}
          />
        </SelectDrop>
        {isComponentVisible && (
          <SelectOptionListContainer>
            <SelectOptionList>
              {filteredOptions.map((option) => (
                <SelectOptionContainer key={option.value} onClick={() => handleSelect(option)}>
                  <SelectOptionText>{option.displayName}</SelectOptionText>
                </SelectOptionContainer>
              ))}
              {noOptions && (
                <SelectOptionContainer>
                  <SelectOptionText>Bank Not Found</SelectOptionText>
                </SelectOptionContainer>
              )}
            </SelectOptionList>
          </SelectOptionListContainer>
        )}
      </SelectContainer>
    </SearchDropdownWrapper>
  )
}

SearchDropdown.propTypes = {
  title: PropTypes.string,
  value: PropTypes.string,
  options: PropTypes.arrayOf(
    PropTypes.shape({
      value: PropTypes.string,
      displayName: PropTypes.string
    })
  ).isRequired,
  onSelect: PropTypes.func.isRequired
}

export default SearchDropdown
