import {
  Container,
  Image,
  LeftContainer,
  MiddleContainerText,
  RightContainer,
  SubTitle,
  TextContainer,
  Title
}
from './claimHeaderUserDetails.style'
import IntlMessages from '../utility/intlMessages'

function ClaimHeaderUserDetails ({
  leftSideIcon = '',
  leftSubTitle = '',
  leftTitle = '',
  middleText = '',
  rightSideIcon = '',
  rightSubTitle = '',
  rightTitle = '',
  isMobile = false
}) {
  return (
    <Container>
      <LeftContainer>
        <Image src={leftSideIcon} />
        <TextContainer>
          <SubTitle>
            <IntlMessages id={leftSubTitle} />
          </SubTitle>
          <Title>{leftTitle}</Title>
        </TextContainer>
      </LeftContainer>
      {middleText && <MiddleContainerText>{middleText}</MiddleContainerText>}
      <RightContainer isMobile={isMobile}>
        <TextContainer>
          <SubTitle>
            <IntlMessages id={rightSubTitle} />
          </SubTitle>
          <Title>{rightTitle}</Title>
        </TextContainer>
        <Image src={rightSideIcon} />
      </RightContainer>
    </Container>
  )
}

export default ClaimHeaderUserDetails
