import { useEffect, useState, useCallback, useRef } from 'react'
import { useFileUploadMutation } from '../request/query/claim/upload'
import { compressImage } from '../helpers/imageCompress'

export const useImageUpload = ({ onImageUplaodSuccess, value }) => {
  const [url, setUrl] = useState(value)
  const [error, setError] = useState(null)
  const lastParamsRef = useRef(null)

  const mutation = useFileUploadMutation({
    onSuccess: ({ url: newUrl }) => {
      setUrl(newUrl)
      setError(null)
      onImageUplaodSuccess(newUrl)
    },
    onError: (err) => {
      setError(err?.response?.data?.message || err?.message || 'Upload failed')
    },
  })

  useEffect(() => {
    setUrl(value)
  }, [value])

  const uploadImage = useCallback(
    async (file, name, claimId, formName, skipCompression, timestamp) => {
      setUrl('')
      setError(null)
      let target = file
      if (file.type.startsWith('image/') && !skipCompression) {
        try {
          target = await compressImage(file)
        } catch (e) {
          // fallback to original file on compression failure
        }
      }
      const params = { file: target, name, claimId, formName, timestamp }
      lastParamsRef.current = params
      mutation.mutate(params)
    },
    [mutation],
  )

  const retryUpload = useCallback(() => {
    if (lastParamsRef.current) {
      setError(null)
      mutation.mutate(lastParamsRef.current)
    }
  }, [mutation])

  return {
    error,
    url,
    loading: mutation.isLoading,
    uploadImage,
    retryUpload,
  }
}
