/* eslint-disable react/jsx-filename-extension */
import React, { useRef, useState, useCallback, useMemo } from 'react'
import {
  DeleteIcon,
  UplaodIcon,
  whiteUploadIcon,
} from '../../image'
import {
  ErrorText,
  ImageUplaodWrapper,
  ImageUploadConatiner,
  ImageUploadBoxContainer,
  Placeholder,
  BoxLabel,
  UploadIconImage,
  ImageShowcase,
  ImageShowCaseWrapper,
  ImageShowCaseTitle,
  WhiteUploadIconContainer,
  WhiteUploadIcon,
  DeleteIconContainer,
  UserguidelineText,
  UserGuidelineImage,
  UserGuidelineBody,
  RetryContainer,
  RetryButton,
  PdfThumbnail,
} from './imageUpload.style'
import Loader from '../Loader'
import Modal from '../Modal'
import UploadSourceModal from '../UploadSourceModal'
import CameraCapture from '../CameraCapture'
import { useImageUpload } from '../../hooks/useImageUpload'
import { getAssets } from '../../helpers/utility'
import { getFileType } from '../../helpers/getFileType'
import FilePreview from '../FilePreview'
import { Document, Page } from 'react-pdf'

const isPdfUrl = (url) => url && getFileType(url) === 'application/pdf'

const ACCEPTED_TYPES = [
  'image/jpeg',
  'image/jpg',
  'image/png',
  'application/pdf',
  'video/mp4',
  'application/msword',
]

const IMAGE_LIMIT_MBS = 10
const VIDEO_LIMIT_MBS = 25
const LOWER_LIMIT_MBS = 0.01

const limitSizeOnType = (type, size) => {
  // TODO: Move to libg
  const lowerLimit = size / 1024 / 1024 < LOWER_LIMIT_MBS
  let upperLimit = size / 1024 / 1024 > IMAGE_LIMIT_MBS

  if (type.includes('video')) {
    upperLimit = size / 1024 / 1024 > VIDEO_LIMIT_MBS
  }

  return { lowerLimit, upperLimit }
}

const UploadError = ({ message, onRetry, loading }) => {
  if (!message) return null
  return (
    <RetryContainer>
      <ErrorText>{message}</ErrorText>
      {onRetry && (
        <RetryButton onClick={onRetry} disabled={loading}>Retry</RetryButton>
      )}
    </RetryContainer>
  )
}

function ImageUplaod({
  disabled,
  value,
  label = '',
  name = '',
  onImageUplaodSuccess = () => {},
  error,
  uploadImageTypeAndSizeText,
  lowerLimitUploadError,
  upperLimitUpladError,
  userGuildeLineImage,
  userGuidelineText = '',
  formName,
  claimId,
  acceptedTypes,
  variant = 'default',
  multiple,
  onFilesSelected,
  onlyCamera,
  onPreview,
}) {
  const inputRef = useRef(null)
  const sourceModalInputRef = useRef(null)
  const [uploadError, setUploadError] = useState(undefined)
  const [showUserGuildelineImage, setShowImageUserGuideline] = useState(false)
  const [imgError, setImgError] = useState(false)
  const [showSourceModal, setShowSourceModal] = useState(false)
  const [showCamera, setShowCamera] = useState(false)
  const [previewOpen, setPreviewOpen] = useState(false)

  const {
    error: uploadGenerateUrlError,
    loading,
    uploadImage,
    retryUpload,
    url,
  } = useImageUpload({ onImageUplaodSuccess, value })

  const pdfFile = useMemo(() => url ? ({ url }) : null, [url])

  const validateFiles = useCallback(
    (files) => {
      const allowedTypes =
        Array.isArray(acceptedTypes) && acceptedTypes.length
          ? acceptedTypes
          : ACCEPTED_TYPES

      for (const file of files) {
        if (!allowedTypes.includes(file.type)) {
          setUploadError(uploadImageTypeAndSizeText)
          return false
        }
        const { lowerLimit, upperLimit } = limitSizeOnType(file.type, file.size)
        if (lowerLimit) {
          setUploadError(lowerLimitUploadError)
          return false
        }
        if (upperLimit) {
          setUploadError(upperLimitUpladError)
          return false
        }
      }
      return true
    },
    [acceptedTypes, uploadImageTypeAndSizeText, lowerLimitUploadError, upperLimitUpladError],
  )

  const handleUploadFile = (e) => {
    e.preventDefault()
    setUploadError('')
    const files = Array.from(e.target.files || [])
    if (inputRef.current) inputRef.current.value = null
    if (files.length === 0) return

    if (!validateFiles(files)) return

    if (onFilesSelected) {
      onFilesSelected(files)
      return
    }

    const file = files[0]
    if (file) {
      uploadImage(file, name, claimId, formName)
    }
  }

  const replaceImageUpload = (e) => {
    e.preventDefault()
    e.stopPropagation()
    setShowSourceModal(true)
  }

  const deleteImageHandler = (e) => {
    e.preventDefault()
    e.stopPropagation()
    onImageUplaodSuccess('')
  }

  const openUserGuidelineModal = (e) => {
    e.preventDefault()
    e.stopPropagation()
    setShowImageUserGuideline(true)
  }

  const imageErrorChangeHandler = () => {
    setImgError(true)
  }

  const handleShowPreview = useCallback(() => {
    if (url) {
      if (onPreview) {
        onPreview(url)
      } else {
        setPreviewOpen(true)
      }
    }
  }, [url, onPreview])

  const handleTapUpload = useCallback(() => {
    if (disabled || loading) return
    setUploadError(undefined)
    setShowSourceModal(true)
  }, [disabled, loading])

  const handleSelectGallery = useCallback(() => {
    setShowSourceModal(false)
    setTimeout(() => {
      if (sourceModalInputRef.current) sourceModalInputRef.current.click()
    }, 100)
  }, [])

  const handleSelectCamera = useCallback(() => {
    setShowSourceModal(false)
    setTimeout(() => setShowCamera(true), 150)
  }, [])

  const handleCameraCapture = useCallback(
    (payload) => {
      setShowCamera(false)
      if (!payload) return
      const isEnrichedMultiple = Array.isArray(payload) && payload.length > 0 && payload[0] && payload[0].file
      const isEnrichedSingle = payload && payload.file
      if (isEnrichedMultiple) {
        const files = payload.map((p) => p.file)
        const timestamps = payload.map((p) => p.timestamp)
        if (!validateFiles(files)) return
        if (onFilesSelected) onFilesSelected(files, timestamps)
        else uploadImage(files[0], name, claimId, formName, true, timestamps[0])
        return
      }
      if (isEnrichedSingle) {
        if (!validateFiles([payload.file])) return
        if (onFilesSelected) onFilesSelected([payload.file], [payload.timestamp])
        else uploadImage(payload.file, name, claimId, formName, true, payload.timestamp)
        return
      }
      const list = Array.isArray(payload) ? payload : [payload]
      if (!validateFiles(list)) return
      if (onFilesSelected) {
        onFilesSelected(payload)
      } else {
        uploadImage(list[0], name, claimId, formName, true)
      }
    },
    [name, claimId, formName, onFilesSelected, uploadImage, validateFiles],
  )

  const handleCloseCamera = useCallback(() => {
    setShowCamera(false)
  }, [])

  const acceptAttr =
    Array.isArray(acceptedTypes) && acceptedTypes.length
      ? acceptedTypes.join(',')
      : ACCEPTED_TYPES.join(',')

  return (
    <ImageUplaodWrapper>
      {url ? (
        <>
          <ImageShowCaseWrapper
            error={uploadError || uploadGenerateUrlError || error}
          >
            <ImageShowCaseTitle>{!url && label}</ImageShowCaseTitle>
            {isPdfUrl(url) && pdfFile ? (
              <PdfThumbnail onClick={handleShowPreview}>
                <Document file={pdfFile}>
                  <Page
                    pageNumber={1}
                    width={200}
                    renderTextLayer={false}
                    renderAnnotationLayer={false}
                  />
                </Document>
              </PdfThumbnail>
            ) : (
              <ImageShowcase
                src={url}
                onClick={handleShowPreview}
                onError={imageErrorChangeHandler}
                style={{ cursor: 'pointer' }}
              />
            )}
            {disabled ? null : (
              <>
                <WhiteUploadIconContainer>
                  <WhiteUploadIcon
                    src={whiteUploadIcon}
                    onClick={replaceImageUpload}
                  />
                </WhiteUploadIconContainer>
                <DeleteIconContainer onClick={deleteImageHandler}>
                  <img src={DeleteIcon} alt='delete' />
                </DeleteIconContainer>
              </>
            )}
          </ImageShowCaseWrapper>
          <UploadError message={uploadError || uploadGenerateUrlError} onRetry={retryUpload} loading={loading} />
        </>
      ) : variant === 'box' ? (
        <>
          <ImageUploadBoxContainer
            error={uploadError || uploadGenerateUrlError || error}
            onClick={handleTapUpload}
          >
            {loading ? <Loader /> : <UploadIconImage src={UplaodIcon} />}
            <BoxLabel>{label}</BoxLabel>
          </ImageUploadBoxContainer>
          <UploadError message={uploadError || uploadGenerateUrlError} onRetry={retryUpload} loading={loading} />
          {userGuildeLineImage ? (
            <UserguidelineText onClick={openUserGuidelineModal}>
              {userGuidelineText}
            </UserguidelineText>
          ) : null}
        </>
      ) : (
        <>
          <ImageUploadConatiner
            error={uploadError || uploadGenerateUrlError || error}
            onClick={handleTapUpload}
          >
            <Placeholder>{!(value || url) && label}</Placeholder>
            {loading ? (
              <Loader />
            ) : (
              <UploadIconImage src={UplaodIcon} />
            )}
          </ImageUploadConatiner>
          <UploadError message={uploadError || uploadGenerateUrlError} onRetry={retryUpload} loading={loading} />
          {userGuildeLineImage ? (
            <UserguidelineText onClick={openUserGuidelineModal}>
              {userGuidelineText}
            </UserguidelineText>
          ) : null}
        </>
      )}
      <input
        type='file'
        ref={(el) => {
          if (el && multiple) el.setAttribute('multiple', '')
          sourceModalInputRef.current = el
          inputRef.current = el
        }}
        onChange={handleUploadFile}
        accept={acceptAttr}
        multiple={multiple}
        onClick={(e) => e.stopPropagation()}
        style={{
          position: 'absolute',
          width: 1,
          height: 1,
          opacity: 0,
          pointerEvents: 'none',
        }}
      />
      {showSourceModal && (
        <UploadSourceModal
          onSelectCamera={handleSelectCamera}
          onSelectGallery={handleSelectGallery}
          onClose={() => setShowSourceModal(false)}
          onlyCamera={onlyCamera}
        />
      )}
      {showCamera && (
        <CameraCapture
          multiple={!!multiple || !!onFilesSelected}
          onCapture={handleCameraCapture}
          onClose={handleCloseCamera}
        />
      )}
      {showUserGuildelineImage ? (
        <Modal
          modalBodyStyle={{
            maxHeight: '80vh',
            height: 'auto',
          }}
          headerText={label}
          markupText={
            <UserGuidelineBody>
              <UserGuidelineImage src={userGuildeLineImage} />
            </UserGuidelineBody>
          }
          onLeftButtonClick={() => setShowImageUserGuideline(false)}
          closeModal={() => setShowImageUserGuideline(false)}
          headerBackgroundColor={getAssets().headerBackgroundColor || ''}
          headerTextColor={getAssets().headerTextColor || ''}
        />
      ) : null}
      {previewOpen && url && (
        <FilePreview files={[{ url }]} onClose={() => setPreviewOpen(false)} />
      )}
    </ImageUplaodWrapper>
  )
}

export default ImageUplaod
