
import { COLORS } from '../../constants/colors'
import { CustomCheckBoxContainer } from './CustomCheckBox.style'

function CustomCheckBox ({
  name,
  disabled,
  onChange,
  checked,
  paddingLeft,
  defaultChecked,
  width = '25px',
  height = '25px',
  checkedBoxLeftAllignment = '0px',
  checkedBoxTopAlignment = '0px',
  borderColor = COLORS.black,
  checkedColor = COLORS.honeyyellow,
  checkedBorderRadius = '4px',
  unCheckedBorderColor = COLORS.black,
  checkedPosition = {},
  ...props
}) {
  return (
    <CustomCheckBoxContainer
      width={width}
      height={height}
      borderColor={borderColor}
      checkedColor={checkedColor}
      paddingLeft={paddingLeft}
      checkedPosition={checkedPosition}
      unCheckedBorderColor={unCheckedBorderColor}
      checkedBorderRadius={checkedBorderRadius}
      checkedBoxTopAlignment={checkedBoxTopAlignment}
      checkedBoxLeftAllignment={checkedBoxLeftAllignment}
    >
      <label className='main'>
        {props.children}
        <input
          data-testid='checkbox'
          name={name}
          type='checkbox'
          disabled={disabled}
          onChange={onChange}
          checked={checked}
          defaultChecked={defaultChecked}
          width={width}
          height={height}
        />
        <span className='geekmark' />
      </label>
    </CustomCheckBoxContainer>
  )
}

export default CustomCheckBox
