/* eslint-disable react/jsx-filename-extension */
import React, { useState, useCallback, useRef, useEffect } from 'react'
import ImageUplaod from '../ImageUpload'
import UploadSourceModal from '../UploadSourceModal'
import CameraCapture from '../CameraCapture'
import FilePreview from '../FilePreview'
import { UplaodIcon } from '../../image'
import { useFileUploadMutation } from '../../request/query/claim/upload'
import { compressImage } from '../../helpers/imageCompress'
import {
  MultiImageUplaodContainer,
  PendingCard,
  FailedCard,
  FileName,
  ErrorMessage,
  RetryButton,
  AddNewWrapper,
  MultiBadge,
  AddNewButton,
  AddNewLabel,
  AddNewIcon,
  ImageGrid,
} from './multiImageUpload.style'
import Loader from '../Loader'

const ACCEPTED_TYPES = [
  'image/jpeg',
  'image/jpg',
  'image/png',
  'application/pdf',
  'video/mp4',
  'application/msword',
]

const IMAGE_LIMIT_MBS = 10
const VIDEO_LIMIT_MBS = 25
const LOWER_LIMIT_MBS = 0.01

const limitSizeOnType = (type, size) => {
  const lowerLimit = size / 1024 / 1024 < LOWER_LIMIT_MBS
  let upperLimit = size / 1024 / 1024 > IMAGE_LIMIT_MBS
  if (type.includes('video')) {
    upperLimit = size / 1024 / 1024 > VIDEO_LIMIT_MBS
  }
  return { lowerLimit, upperLimit }
}

function MultiImageUpload({
  name,
  value,
  label,
  onImageUplaodSuccess,
  error,
  disabled,
  uploadImageTypeAndSizeText,
  lowerLimitUploadError,
  upperLimitUpladError,
  userGuildeLineImage,
  userGuidelineText,
  formName,
  claimId,
  acceptedTypes,
  onlyCamera,
}) {
  const safeValue = Array.isArray(value) ? value : []
  const safeValueRef = useRef(safeValue)
  useEffect(() => { safeValueRef.current = safeValue }, [safeValue])
  const [pendingItems, setPendingItems] = useState([])
  const [showSourceModal, setShowSourceModal] = useState(false)
  const [showCamera, setShowCamera] = useState(false)
  const [previewIndex, setPreviewIndex] = useState(-1)
  const idRef = useRef(0)
  const fileInputRef = useRef(null)

  const uploadMutation = useFileUploadMutation()
  const retryMutation = useFileUploadMutation()

  const uploadFilesBatch = useCallback(
    async (filesOrEnriched) => {
      const normalized = filesOrEnriched.map((entry) => {
        if (entry && entry.file) return entry
        return { file: entry, timestamp: undefined }
      })
      const newItems = normalized.map(({ file, timestamp }) => ({
        id: ++idRef.current,
        file,
        name: file.name,
        status: 'uploading',
        url: null,
        error: null,
        timestamp,
      }))

      setPendingItems((prev) => [...prev, ...newItems])

      const results = await Promise.allSettled(
        normalized.map(({ file, timestamp }) => uploadMutation.mutateAsync({ file, name, claimId, formName, timestamp })),
      )

      const updatedItems = []
      const successfulUrls = []

      results.forEach((result, i) => {
        if (result.status === 'fulfilled') {
          updatedItems.push({
            ...newItems[i],
            status: 'done',
            url: result.value.url,
          })
          successfulUrls.push(result.value.url)
        } else {
          const errMsg =
            result.reason?.response?.data?.message ||
            result.reason?.message ||
            'Upload failed'
          updatedItems.push({
            ...newItems[i],
            status: 'failed',
            error: errMsg,
          })
        }
      })

      setPendingItems((prev) => {
        const withoutNew = prev.filter(
          (p) => !newItems.find((n) => n.id === p.id),
        )
        return [...withoutNew, ...updatedItems]
      })

      if (successfulUrls.length === 0) return

      const newValue = [...safeValueRef.current, ...successfulUrls]
      onImageUplaodSuccess(newValue)
      setPendingItems((prev) => prev.filter((p) => p.status !== 'done'))
    },
    [name, claimId, formName, onImageUplaodSuccess, uploadMutation],
  )

  const handleFilesSelected = useCallback(
    async (files, timestampsOrSkip) => {
      const skipCompression = timestampsOrSkip === true || Array.isArray(timestampsOrSkip)
      const timestamps = Array.isArray(timestampsOrSkip) ? timestampsOrSkip : undefined
      const validEntries = []
      for (let i = 0; i < files.length; i++) {
        const f = files[i]
        validEntries.push({ file: f, timestamp: timestamps ? timestamps[i] : undefined })
      }
      if (skipCompression) {
        uploadFilesBatch(validEntries)
        return
      }
      const compressedEntries = await Promise.all(
        validEntries.map(async ({ file, timestamp }) => {
          if (!file.type.startsWith('image/')) return { file, timestamp }
          try {
            return { file: await compressImage(file), timestamp }
          } catch (e) {
            return { file, timestamp }
          }
        }),
      )
      uploadFilesBatch(compressedEntries)
    },
    [uploadFilesBatch],
  )

  const pendingItemsRef = useRef(pendingItems)
  pendingItemsRef.current = pendingItems

  const handleRetry = useCallback(async (itemId) => {
    const item = pendingItemsRef.current.find((p) => p.id === itemId)
    if (!item || !item.file) return

    setPendingItems((prev) =>
      prev.map((p) =>
        p.id === itemId ? { ...p, status: 'uploading', error: null } : p
      )
    )

    try {
      const result = await retryMutation.mutateAsync({ file: item.file, name, claimId, formName, timestamp: item.timestamp })

      setPendingItems((prev) =>
        prev.map((p) =>
          p.id === itemId ? { ...p, status: 'done', url: result.url } : p
        )
      )

      const newValue = [...safeValueRef.current, result.url]
      onImageUplaodSuccess(newValue)
      setPendingItems((prev) => prev.filter((p) => p.id !== itemId))
    } catch (err) {
      const errMsg =
        err?.response?.data?.message || err?.message || 'Upload failed'
      setPendingItems((prev) =>
        prev.map((p) =>
          p.id === itemId ? { ...p, status: 'failed', error: errMsg } : p
        )
      )
    }
  }, [name, claimId, formName, onImageUplaodSuccess, retryMutation])

  const handleSelectGallery = useCallback(() => {
    setShowSourceModal(false)
    setTimeout(() => {
      if (fileInputRef.current) fileInputRef.current.click()
    }, 100)
  }, [])

  const handleSelectCamera = useCallback(() => {
    setShowSourceModal(false)
    setTimeout(() => setShowCamera(true), 150)
  }, [])

  const handleCameraCapture = useCallback(
    (payload) => {
      setShowCamera(false)
      if (!payload) return
      const enriched = Array.isArray(payload) ? payload : [payload]
      if (enriched.length === 0) return
      const files = enriched.map((e) => (e && e.file ? e.file : e))
      const timestamps = enriched.map((e) => (e && e.timestamp ? e.timestamp : undefined))
      const hasTimestamp = timestamps.some(Boolean)
      for (const file of files) {
        if (!Array.isArray(acceptedTypes) || !acceptedTypes.length) {
          if (!ACCEPTED_TYPES.includes(file.type)) return
        } else if (!acceptedTypes.includes(file.type)) return
        const { lowerLimit, upperLimit } = limitSizeOnType(file.type, file.size)
        if (lowerLimit || upperLimit) return
      }
      if (hasTimestamp) {
        uploadFilesBatch(enriched)
      } else {
        uploadFilesBatch(files)
      }
    },
    [uploadFilesBatch, acceptedTypes],
  )

  const failedItems = pendingItems.filter((p) => p.status === 'failed')
  const uploadingItems = pendingItems.filter(
    (p) => p.status === 'uploading'
  )
  const doneItems = pendingItems.filter((p) => p.status === 'done')
  const isUploading = uploadingItems.length > 0 || uploadMutation.isPending || retryMutation.isPending

  const handlePreview = useCallback((url) => {
    const idx = safeValue.findIndex((u) => u === url)
    if (idx !== -1) setPreviewIndex(idx)
  }, [safeValue])

  return (
    <MultiImageUplaodContainer>
      {(safeValue.length > 0 || failedItems.length > 0 || uploadingItems.length > 0 || doneItems.length > 0) && (
        <ImageGrid>
          {safeValue.map((url, index) => (
            <ImageUplaod
              key={`${url}_${index + 1}`}
              disabled={disabled}
              value={url}
              label={label}
              formName={formName}
              claimId={claimId}
              variant='box'
              error={error}
              onImageUplaodSuccess={(newUrl) => {
                if (!newUrl) {
                  const newValue = safeValue.filter((_, i) => i !== index)
                  onImageUplaodSuccess(newValue)
                } else {
                  const newValue = safeValue.map((item, i) =>
                    i === index ? newUrl : item
                  )
                  onImageUplaodSuccess(newValue)
                }
              }}
              acceptedTypes={acceptedTypes}
              uploadImageTypeAndSizeText={uploadImageTypeAndSizeText}
              lowerLimitUploadError={lowerLimitUploadError}
              upperLimitUpladError={upperLimitUpladError}
              userGuildeLineImage={userGuildeLineImage}
              userGuidelineText={userGuidelineText}
              onPreview={handlePreview}
            />
          ))}
          {uploadingItems.map((item) => (
            <PendingCard key={item.id}>
              <Loader />
              <FileName>{item.name}</FileName>
            </PendingCard>
          ))}
          {doneItems.map((item) => (
            <PendingCard key={item.id}>
              <FileName>{item.name}</FileName>
            </PendingCard>
          ))}
          {failedItems.map((item) => (
            <FailedCard key={item.id}>
              <FileName>{item.name}</FileName>
              <ErrorMessage>{item.error}</ErrorMessage>
              <RetryButton onClick={() => handleRetry(item.id)} disabled={retryMutation.isPending}>
                Retry
              </RetryButton>
            </FailedCard>
          ))}
        </ImageGrid>
      )}
      {disabled || isUploading ? null : (
        <AddNewWrapper>
          <AddNewButton onClick={() => setShowSourceModal(true)}>
            <AddNewLabel>{label}</AddNewLabel>
            <AddNewIcon src={UplaodIcon} />
          </AddNewButton>
          <input
            type='file'
            ref={(el) => {
              if (el) el.setAttribute('multiple', '')
              fileInputRef.current = el
            }}
            onClick={(e) => e.stopPropagation()}
            onChange={(e) => {
              const files = Array.from(e.target.files || [])
              if (fileInputRef.current) fileInputRef.current.value = null
              if (!files.length) return

              const allowedTypes =
                Array.isArray(acceptedTypes) && acceptedTypes.length
                  ? acceptedTypes
                  : ACCEPTED_TYPES

              for (const file of files) {
                if (!allowedTypes.includes(file.type)) return
                const { lowerLimit, upperLimit } = limitSizeOnType(file.type, file.size)
                if (lowerLimit || upperLimit) return
              }

              handleFilesSelected(files)
            }}
            accept={
              Array.isArray(acceptedTypes) && acceptedTypes.length
                ? acceptedTypes.join(',')
                : 'image/jpeg,image/jpg,image/png,application/pdf,video/mp4,application/msword'
            }
            multiple
            style={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: 1,
              height: 1,
              opacity: 0,
              overflow: 'hidden',
            }}
          />
          <MultiBadge>Multiple</MultiBadge>
        </AddNewWrapper>
      )}
      {showSourceModal && (
        <UploadSourceModal
          onSelectCamera={handleSelectCamera}
          onSelectGallery={handleSelectGallery}
          onClose={() => setShowSourceModal(false)}
          onlyCamera={onlyCamera}
        />
      )}
      {showCamera && (
        <CameraCapture
          multiple
          onCapture={handleCameraCapture}
          onClose={() => setShowCamera(false)}
        />
      )}
      {previewIndex !== -1 && safeValue.length > 0 && (
        <FilePreview
          files={safeValue.map((u) => ({ url: u }))}
          initialIndex={previewIndex}
          onClose={() => setPreviewIndex(-1)}
        />
      )}
    </MultiImageUplaodContainer>
  )
}

export default MultiImageUpload
