import { useQuery } from '@tanstack/react-query'
import request from '../axios/claim'

export const BENGKELNET_PROVINCE_LIST_KEY = 'bengkelnet-province_list'
export const BENGKELNET_CITY_LIST_KEY = 'bengkelnet-city_list'
export const BENGKELNET_WORKSHOP_LIST_KEY = 'bengkelnet-workshop_list'

export const useBengkelnetProvinceList = (options) =>
  useQuery({
    queryKey: [BENGKELNET_PROVINCE_LIST_KEY],
    queryFn: () =>
      request.getBengkelnetProvinceList().then((res) => res.data),
    ...options
  })

export const useBengkelnetCityList = (provinceId, options) =>
  useQuery({
    queryKey: [BENGKELNET_CITY_LIST_KEY, provinceId],
    queryFn: () =>
      request.getBengkelnetCityList({ province_id: provinceId }).then((res) => res.data),
    enabled: !!provinceId,
    ...options
  })

export const useBengkelnetWorkshopList = (provinceId, cityId, claimId, options) =>
  useQuery({
    queryKey: [BENGKELNET_WORKSHOP_LIST_KEY, provinceId, cityId, claimId],
    queryFn: () =>
      request.getBengkelnetWorkshopList({
        province_id: provinceId,
        city_id: cityId,
        claim_id: claimId
      }).then((res) => res.data),
    enabled: !!(provinceId && cityId && claimId),
    ...options
  })
