const pad = (n) => String(n).padStart(2, '0')

export const toWatermarkString = (d) => {
  const offset = -d.getTimezoneOffset()
  const hours = Math.floor(Math.abs(offset) / 60)
  const mins = Math.abs(offset) % 60
  const sign = offset >= 0 ? '+' : '-'
  const offsetStr = `(UTC${sign}${hours}${mins ? `:${pad(mins)}` : ''})`
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())} ${offsetStr}`
}

export const toApiFields = (d) => {
  const offset = -d.getTimezoneOffset()
  const offHours = Math.floor(Math.abs(offset) / 60)
  const offMins = Math.abs(offset) % 60
  const sign = offset >= 0 ? '+' : '-'
  return {
    timestamp_date: `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`,
    timestamp_time: `${pad(d.getHours())}:${pad(d.getMinutes())}`,
    timestamp_utc_offset: `${sign}${offHours}:${pad(offMins)}`,
  }
}
