import React, { useEffect, useRef, useState } from 'react'
import html2canvas from 'html2canvas'
import { ButtonContainer, CarContainer, CarImage, Container, Marker, SketchImage } from './CarSketch.style'
import { Button } from 'antd'
import { useImageUpload } from '../../hooks/useImageUpload'
import Loader from '../Loader'
import { ErrorText } from '../ImageUpload/imageUpload.style'
import IntlMessages from '../utility/intlMessages'

const CarSketch = ({ claim_id, onImageGenerated, name, formName, value, disabled = false }) => {
  const imageRef = useRef(null)
  const removeRef = useRef(null)
  const [selectedParts, setSelectedParts] = useState([])
  const [file, setFile] = useState(null)
  const [svgContent, setSvgContent] = useState('')
  const [error, setError] = useState(null)

  const {
    error: uploadGenerateUrlError,
    loading,
    url,
    uploadImage
  } = useImageUpload({
    onImageUplaodSuccess: onImageGenerated,
    value: file
  })


  useEffect(() => {
    if (disabled) setSelectedParts([])
  }, [disabled])

  useEffect(() => {
    // Fetch SVG content from GCP and inject it as inline SVG
    fetch('https://pp-img-prod.s3.ap-southeast-3.amazonaws.com/tap-auto/Car+Frame.svg')
      .then(res => res.text())
      .then(setSvgContent)
      .catch(err => console.error('Failed to load SVG', err))
  }, [])

  const toggleMarker = (event) => {
    if (disabled) return
    if (!imageRef.current) return

    const rect = imageRef.current.getBoundingClientRect()
    const offsetX = ((event.clientX - rect.left) / rect.width) * 100
    const offsetY = ((event.clientY - rect.top) / rect.height) * 100

    const newMarker = { id: `${offsetX}-${offsetY}`, top: `${offsetY}%`, left: `${offsetX}%` }

    setSelectedParts((prev) => {
      const exists = prev.find((p) => p.id === newMarker.id)
      return exists ? prev.filter((p) => p.id !== newMarker.id) : [...prev, newMarker]
    })
  }

  const clearAllMarkers = () => {
    setSelectedParts([])
  }

  const handleSaveSketch = async () => {
    if (!imageRef.current) return
    if (selectedParts.length === 0) {
      setError('Please select at least one part.')
      return
    }
    const canvas = await html2canvas(imageRef.current)
    const timestamp = new Date().toISOString().replace(/[-:.TZ]/g, '')

    canvas.toBlob((blob) => {
      if (!blob) return
      const sketchFile = new File(
        [blob],
        `car-sketch_${claim_id}_${timestamp}.png`,
        { type: 'image/png' }
      )
      setFile(sketchFile)
      uploadImage(sketchFile, name, claim_id, formName)
    })
  }

  const handleEditSketch = (e) => {
    e.preventDefault()
    e.stopPropagation()
    onImageGenerated('')
    clearAllMarkers()
  }

  return loading ? (
    <Loader />
  ) : (

    <Container>
      {value ? (
        <>
          <SketchImage src={value} alt='car sketch' />
          {!disabled && (
            <>
              <input type='file' ref={removeRef} hidden onChange={handleSaveSketch} />
              <ButtonContainer>
                <Button onClick={handleEditSketch} type='danger'>
                  Edit Sketch
                </Button>
              </ButtonContainer>
            </>
          )}
        </>
      ) : (
        <>
          <CarContainer onClick={disabled ? undefined : toggleMarker} ref={imageRef}>
          <CarImage dangerouslySetInnerHTML={{ __html: svgContent }}/>
              {selectedParts.map(({ id, top, left }) => (
              <Marker key={id} style={{ top, left }}>
                  X
              </Marker>
              ))}
          </CarContainer>
          {!disabled && (
          <ButtonContainer>
              <Button onClick={clearAllMarkers} type="danger">
              Clear Marker
              </Button>
              <Button onClick={handleSaveSketch} type="primary">
              Save Sketch
              </Button>
          </ButtonContainer>
          )}
        </>
      )}
      {uploadGenerateUrlError && <ErrorText>{uploadGenerateUrlError}</ErrorText>}
      {error && <ErrorText><IntlMessages id={error}/></ErrorText>}
    </Container>
  )
}

export default CarSketch
