export function getFileType(file) {
  if (!file) return 'image/png'

  if (typeof file === 'string' && file.startsWith('http')) {
    const cleanUrl = file.split('?')[0].split('#')[0]
    if (cleanUrl.endsWith('.png')) return 'image/png'
    if (cleanUrl.endsWith('.jpeg')) return 'image/jpeg'
    if (cleanUrl.endsWith('.jpg')) return 'image/jpg'
    if (cleanUrl.endsWith('.webp')) return 'image/webp'
    if (cleanUrl.endsWith('.gif')) return 'image/gif'
    if (cleanUrl.endsWith('.pdf')) return 'application/pdf'
    if (cleanUrl.endsWith('.doc')) return 'application/msword'
    if (cleanUrl.endsWith('.mp4')) return 'video/mp4'
    return 'image/png'
  }

  for (let i = 0; i < 100; i++) {
    if (file[i] === ';') {
      return file.slice(5, i)
    }
  }

  return 'image/png'
}
