import { useState } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { FormattedMessage } from 'react-intl'

import claimActions from '../../../redux/claim/actions'
import { LANG_STRINGS } from '../../../constants/lang'
import TextInput from '../../../components/Textinput'
import { useRemoveErrorActionsHelper, useRemoveLoadingActionsHelper } from '../../../helpers/utility'
import Loader from '../../../components/Loader'
import IntlMessages from '../../../components/utility/intlMessages'
import {
  GoPayWalletContainer,
  Label,
  SaveButton,
  ErrorBanner,
  Value,
  InputContainer
} from './paymentForm.style'

function GoPayWallet ({
  claimData,
  form,
  handleSubmit
}) {
  const { attributes, name: formName } = form
  const bankCode = attributes.find(({ name }) => name === 'bank_name')?.value
  const { claim_no: claimNo, claim_id: claimId } = claimData
  const dispatch = useDispatch()
  const verifyBankAccountloading = useRemoveLoadingActionsHelper(claimActions.VERIFY_BANK_ACCOUNT_FORMS_REQUEST)
  const verifyBankAccountError = useRemoveErrorActionsHelper(claimActions.VERIFY_BANK_ACCOUNT_FORMS_REQUEST)
  const verifyBankAccountFormStatus = useSelector((state) => state.Claim.verifyBankAccountFormStatus)
  const verifyAccountData = useSelector((state) => state.Claim.verifyAccountData || {})
  const { account_holder_name: accountHolderName, is_valid: accountHolderVerified } = verifyAccountData
  const [payloadData, setPayload] = useState({})
  const verifyBankAccount = () => {
    const payload = {
      account_number: payloadData.account_number,
      bank_name: bankCode
    }
    dispatch(claimActions.verifyBankAccountForms({ payload }))
  }

  const changeHandler = ({ value, name }) => {
    setPayload((payload) => ({
      ...payload,
      [name]: value
    }))
  }

  const saveBankAccount = () => {
    const body = {
      claim_id: claimId,
      form: formName,
      payload: {
        ...payloadData,
        'account_holder_name': accountHolderName,
        claim_no: claimNo,
        source: 'direct'
      }
    }
    if (handleSubmit) {
      handleSubmit(body)
    }
  }

  return (
    <GoPayWalletContainer>
      <InputContainer>
        <Label>
          <FormattedMessage id={LANG_STRINGS.acocuntNumber} />
        </Label>
        <TextInput onChange={changeHandler} name='account_number' form={form} />
      </InputContainer>
      {
        accountHolderVerified
          ? <InputContainer>
            <Label>
              <FormattedMessage id={LANG_STRINGS.accountHolderName} />
            </Label>
            <Value>{accountHolderName}</Value>
          </InputContainer>
          : null
      }
      {
        verifyBankAccountFormStatus && verifyBankAccountError
          ? (
            <ErrorBanner>
              {verifyBankAccountFormStatus}
            </ErrorBanner>
          )
          : null
      }
      {
        accountHolderVerified
          ? <SaveButton
            onClick={saveBankAccount}
          >
            {verifyBankAccountloading && <Loader />}
            <IntlMessages id={LANG_STRINGS.submitLabel} />
          </SaveButton>
          : <SaveButton
            onClick={verifyBankAccount}
          >
            {verifyBankAccountloading && <Loader />}
            <IntlMessages id={LANG_STRINGS.saveBankAccount} />
          </SaveButton>
      }
    </GoPayWalletContainer>
  )
}

export default GoPayWallet
