import React, { useState, useCallback, useRef, useEffect } from 'react'
import Lightbox from 'react-image-lightbox'
import 'react-image-lightbox/style.css'
import { Document, Page } from 'react-pdf'
import { getFileType } from '../../helpers/getFileType'
import { DocumentIcon } from '../../image'
import {
  Overlay,
  Content,
  PreviewImage,
  PdfContainer,
  Video,
  CloseButton,
  NavLeft,
  NavRight,
  Toolbar,
  ToolButton,
  DocIcon,
  DocLabel,
  DocLink,
} from './index.style'

const IMAGE_TYPES = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp', 'image/gif']

const isImageType = (url) => {
  const type = getFileType(url)
  if (IMAGE_TYPES.includes(type)) return true
  const cleanUrl = (url || '').split('?')[0]
  return /\.(jpe?g|png|webp|gif)$/i.test(cleanUrl)
}

function FilePreview({ files, initialIndex = 0, onClose }) {
  const [currentIndex, setCurrentIndex] = useState(initialIndex)
  const [zoom, setZoom] = useState(1)
  const [pan, setPan] = useState({ x: 0, y: 0 })
  const [numPages, setNumPages] = useState(0)
  const dragRef = useRef(null)
  const imgRef = useRef(null)

  const fileList = (files || []).map((f) => (typeof f === 'string' ? { url: f } : f))
  const allImages = fileList.length && fileList.every((f) => f && isImageType(f.url))

  useEffect(() => {
    setZoom(1)
    setPan({ x: 0, y: 0 })
    setNumPages(0)
  }, [currentIndex])

  useEffect(() => {
    const prev = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    return () => { document.body.style.overflow = prev }
  }, [])

  useEffect(() => {
    const el = imgRef.current
    if (!el) return
    const handler = (e) => {
      e.preventDefault()
      setZoom((z) => Math.max(0.5, Math.min(3, z - e.deltaY * 0.002)))
    }
    el.addEventListener('wheel', handler, { passive: false })
    return () => el.removeEventListener('wheel', handler)
  }, [currentIndex])

  const handlePrev = useCallback(() => {
    setCurrentIndex((i) => (i + fileList.length - 1) % fileList.length)
  }, [fileList.length])

  const handleNext = useCallback(() => {
    setCurrentIndex((i) => (i + 1) % fileList.length)
  }, [fileList.length])

  useEffect(() => {
    if (allImages) return
    const handler = (e) => {
      if (e.key === 'Escape') onClose()
      else if (e.key === 'ArrowLeft') handlePrev()
      else if (e.key === 'ArrowRight') handleNext()
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [allImages, onClose, handlePrev, handleNext])

  const handleMouseDown = useCallback((e) => {
    if (zoom <= 1) return
    dragRef.current = { startX: e.clientX - pan.x, startY: e.clientY - pan.y }
  }, [zoom, pan])

  const handleMouseMove = useCallback((e) => {
    if (!dragRef.current) return
    setPan({ x: e.clientX - dragRef.current.startX, y: e.clientY - dragRef.current.startY })
  }, [])

  const handleMouseUp = useCallback(() => {
    dragRef.current = null
  }, [])

  const zoomIn = useCallback(() => setZoom((z) => Math.min(z + 0.5, 3)), [])
  const zoomOut = useCallback(() => setZoom((z) => Math.max(z - 0.5, 0.5)), [])
  const zoomReset = useCallback(() => { setZoom(1); setPan({ x: 0, y: 0 }) }, [])

  if (allImages && fileList.length > 0) {
    const urls = fileList.map((f) => f.url)
    return (
      <Lightbox
        mainSrc={urls[currentIndex]}
        nextSrc={urls.length > 1 ? urls[(currentIndex + 1) % urls.length] : undefined}
        prevSrc={urls.length > 1 ? urls[(currentIndex + urls.length - 1) % urls.length] : undefined}
        onCloseRequest={onClose}
        onMovePrevRequest={handlePrev}
        onMoveNextRequest={handleNext}
        reactModalStyle={{ overlay: { zIndex: 10000 } }}
      />
    )
  }

  const current = fileList[currentIndex]
  if (!current) return null

  const currentUrl = current.url
  const currentType = current.type || getFileType(currentUrl)
  const isImage = IMAGE_TYPES.includes(currentType)
  const isPdf = currentType === 'application/pdf'
  const isVideo = currentType === 'video/mp4'
  const isDoc = currentType === 'application/msword'

  return (
    <Overlay onClick={onClose}>
      <CloseButton onClick={onClose}>&times;</CloseButton>

      {fileList.length > 1 && (
        <>
          <NavLeft onClick={(e) => { e.stopPropagation(); handlePrev() }}>
            &#8249;
          </NavLeft>
          <NavRight onClick={(e) => { e.stopPropagation(); handleNext() }}>
            &#8250;
          </NavRight>
        </>
      )}

      {isImage && (
        <Toolbar>
          <ToolButton onClick={zoomIn} disabled={zoom >= 3}>+</ToolButton>
          <ToolButton onClick={zoomOut} disabled={zoom <= 0.5}>-</ToolButton>
          <ToolButton onClick={zoomReset}>Reset</ToolButton>
        </Toolbar>
      )}

      <Content onClick={(e) => e.stopPropagation()}>
        {isImage && (
          <PreviewImage
            ref={imgRef}
            src={currentUrl}
            alt="preview"
            onMouseDown={handleMouseDown}
            onMouseMove={handleMouseMove}
            onMouseUp={handleMouseUp}
            onMouseLeave={handleMouseUp}
            style={{
              transform: `scale(${zoom})${zoom > 1 ? ` translate(${pan.x}px, ${pan.y}px)` : ''}`,
              transition: 'transform 0.2s ease',
              cursor: zoom > 1 ? 'grab' : 'zoom-in',
            }}
            draggable={false}
          />
        )}
        {isPdf && (
          <PdfContainer>
            <Document
              file={{ url: currentUrl }}
              onLoadSuccess={({ numPages }) => setNumPages(numPages)}
            >
              {Array.from({ length: numPages }, (_, i) => (
                <Page
                  key={`pdf-page-${i + 1}`}
                  pageNumber={i + 1}
                  width={Math.min(window.innerWidth * 0.85, 800)}
                  renderTextLayer={false}
                  renderAnnotationLayer={false}
                />
              ))}
            </Document>
          </PdfContainer>
        )}
        {isVideo && (
          <Video src={currentUrl} controls autoPlay />
        )}
        {isDoc && (
          <div style={{ textAlign: 'center' }}>
            <DocIcon src={DocumentIcon} alt="document" />
            <DocLabel>Document file</DocLabel>
            <DocLink href={currentUrl} target="_blank" rel="noreferrer">
              Open in new tab
            </DocLink>
          </div>
        )}
      </Content>
    </Overlay>
  )
}

export default FilePreview
