export const StatusContainer = styled.div`
  display: flex;
  padding: 32px;
  flex-direction: column;
  align-items: flex-start;
  gap: 8px;
  align-self: stretch;
  border-radius: 8px;

  background-color: ${props => {
    if (props.status === STATUS_GROUP_INITIATED) {
      return COLORS.lightYellow
    } else if (props.status === STATUS_GROUP_DOC_REPROCESS) {
      return COLORS.lightVoilet
    } else if (props.status === STATUS_GROUP_SETTLED) {
      return COLORS.lightGreen
    } else if (props.status === STATUS_GROUP_REJECTED) {
      return COLORS.lightRed
    } else {
      return COLORS.lightBlue
    }
  }};

  color: ${props => {
    if (props.status === STATUS_GROUP_INITIATED) {
      return COLORS.originGold
    } else if (props.status === STATUS_GROUP_DOC_REPROCESS) {
      return COLORS.mysticVoilet
    } else if (props.status === STATUS_GROUP_SETTLED) {
      return COLORS.grassGreen
    } else if (props.status === STATUS_GROUP_REJECTED) {
      return COLORS.crimsonRed
    } else {
      return COLORS.tapPartnerBlue
    }
  }};
`

