import { useEffect, useState } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { useHistory, useParams } from 'react-router'
import claimActions from '../../redux/claim/actions'
import userActions from '../../redux/user/actions'
import errorActions from '../../redux/error/actions'
import ClaimDetailHeader from './ClaimDetailHeader'
import {
  removeActionStateAndReturnMatches,
  useRemoveErrorActionsHelper,
  useRemoveLoadingActionsHelper
} from '../../helpers/utility'
import Loader from '../../components/Loader'
import {
  LoaderContainer,
  ClaimDetailStyleContainer,
  Center
} from './claimDetailHeader.style'
import ClaimMainDetail from './ClaimMainDetail'
import ClaimForm from './ClaimForm'
import PaymentForms from './PaymentForms/paymentForm'
import ClaimFamilyDetails from './ClaimFamilyDetails'
import { useIsMobile } from '../../hooks/useIsMobile'

function ClaimDetailContainer () {
  const dispatch = useDispatch()
  const history = useHistory()

  const isClaimDetailLoading = useRemoveLoadingActionsHelper(claimActions.GET_CLAIM_DETAILS_REQUEST)
  const isClaimDetailError = useRemoveErrorActionsHelper(claimActions.GET_CLAIM_DETAILS_REQUEST)
  const params = useParams()
  const isMobile = useIsMobile()
  const { id = '' } = params
  const claimdetailsData = useSelector((state) => state.Claim.claimDetails)
  const bankList = useSelector((state) => state.Claim.claimBankList)
  const associatedUserList = useSelector((state) => state.Claim.associatedUserList)

  const [activePolicyFilter, setActivePolicyFilter] = useState('detail')
  const [isTabFixed, setIsTabFixed] = useState(false)

  const handleScroll = () => {
    const policyTab = document.querySelector('.detail-header')
    if (policyTab) {
      const policyTabTop = policyTab.getBoundingClientRect().bottom
      setIsTabFixed(policyTabTop <= 0)
    }
  }

  useEffect(() => {
    if (isClaimDetailError) {
      dispatch(errorActions.resetErrorRedux(removeActionStateAndReturnMatches(claimActions.GET_CLAIM_DETAILS_REQUEST)))
      history.push('/')
    }
  }, [isClaimDetailError, dispatch, history])

  useEffect(() => {
    dispatch(claimActions.getClaimDetails(id))
    dispatch(claimActions.getAssocaitedUserOnClaim(id))
    dispatch(claimActions.getClaimBankList({ claim_id: id }))
    return () => {
      dispatch(claimActions.resetReduxState(['claimDetails', 'associatedUserList', 'claimBankList']))
    }
  }, [id, dispatch])

  useEffect(() => {
    dispatch(userActions.getUserDetails())
  }, [dispatch])

  useEffect(() => {
    window.addEventListener('scroll', handleScroll)
    return () => {
      window.removeEventListener('scroll', handleScroll)
    }
  }, [])

  return (
    <ClaimDetailStyleContainer data-testid='claim-detail'>
      {isClaimDetailLoading ? (
        <LoaderContainer>
          <Loader />
        </LoaderContainer>
      ) : null}
      {claimdetailsData && Object.keys(claimdetailsData).length ? (
        <>
          <div className='detail-header'>
            <ClaimDetailHeader claimData={claimdetailsData} />
          </div>
          {isMobile ? (
            <>
              <div className={`claims-tab ${isTabFixed ? 'fixed' : ''}`}>
                <button className={activePolicyFilter === 'detail' ? 'active' : ''} onClick={() => setActivePolicyFilter('detail')}>
                  Klaim Detail
                </button>
                <button className={activePolicyFilter === 'forms' ? 'active' : ''} onClick={() => setActivePolicyFilter('forms')}>
                  Klaim Form
                </button>
              </div>
              {activePolicyFilter === 'detail' ? (
                <Center>
                  <ClaimMainDetail claimData={claimdetailsData} />
                </Center>
              ) : (
                <>
                  <Center>
                    <ClaimForm bankList={bankList} claimData={claimdetailsData} />
                  </Center>
                  <Center>
                    <PaymentForms bankList={bankList} claimData={claimdetailsData} />
                  </Center>
                </>
              )}
            </>
          ) : (
            <>
              <Center>
                <ClaimFamilyDetails userList={associatedUserList} />
              </Center>
              <Center>
                <ClaimMainDetail claimData={claimdetailsData} />
              </Center>
              <Center>
                <ClaimForm bankList={bankList} claimData={claimdetailsData} />
              </Center>
              <Center>
                <PaymentForms bankList={bankList} claimData={claimdetailsData} />
              </Center>
            </>
          )}
        </>
      ) : null}
    </ClaimDetailStyleContainer>
  )
}

export default ClaimDetailContainer
