import { useEffect } from 'react'
import { FormattedMessage } from 'react-intl'
import { connect } from 'react-redux'
import {
  InforWrapper,
  AddressFormWrapper,
  ServiceCenterShowForm,
  ServiceCenterTitle,
  TagTitle,
  TagContent,
  ViewServiceCenterFormWrapper
} from './ClaimServiceStyle'

import claimActions from '../../redux/claim/actions'
import IntlMessages from '../utility/intlMessages'
import { LANG_STRINGS } from '../../constants/lang'

const {
  getServiceCenterBrandList,
  getTotalServiceCenter
} = claimActions

function ViewServiceCenterForm ({
  claimId,
  serviceCenterBrandList,
  getServiceCenterBrandList,
  totalServiceCenterList = [],
  serviceCenterForm = {},
  getTotalServiceCenter
}) {
  const { attributes = [] } = serviceCenterForm

  const { branch_info: branchInfo = {} } = attributes.find(({ name }) => name === 'servicecenter_branch') || {}

  const branchNameAndAddress = `${branchInfo.branch_name} -  ${branchInfo.address}`

  const payload = {}

  attributes.forEach(att => {
    const { name, value } = att
    payload[name] = value
  })

  useEffect(() => {
    getServiceCenterBrandList()
    getTotalServiceCenter()
  }, [])

  return (
    <ViewServiceCenterFormWrapper>

      {
        payload.sc_brand
          ? (
            <AddressFormWrapper>
              <ServiceCenterTitle>
                <IntlMessages
                  id={LANG_STRINGS.detailBrand}
                />
              </ServiceCenterTitle>

              <InforWrapper >
                <div>
                  <TagTitle>
                    <IntlMessages id={LANG_STRINGS.brandLabel} />
                  </TagTitle>
                  <TagContent >
                    {serviceCenterBrandList.find(({ id }) => id === payload.sc_brand)?.name}
                  </TagContent>
                </div>
              </InforWrapper>

            </AddressFormWrapper>
          )

          : null
      }

      <AddressFormWrapper>

        <ServiceCenterTitle>
          <FormattedMessage
            id='Detail area perbaikan'
            defaultMessage='Detail area perbaikan'
          />
        </ServiceCenterTitle>

        <InforWrapper>

          <div>
            <TagTitle>
              <FormattedMessage
                id='Propinsi'
                defaultMessage='Propinsi'
              />
            </TagTitle>
            <TagContent>
              {payload['sc_province']}
            </TagContent>
          </div>

          <div>
            <TagTitle>
              <FormattedMessage
                id='Kota'
                defaultMessage='Kota'
              />
            </TagTitle>
            <TagContent>
              {payload['sc_city']}
            </TagContent>

          </div>

          <div>
            <TagTitle>
              <FormattedMessage
                id='Kode pos'
                defaultMessage='Kode pos'
              />
            </TagTitle>
            <TagContent>
              {payload['sc_postal_code']}
            </TagContent>

          </div>

        </InforWrapper>

      </AddressFormWrapper>

      <ServiceCenterShowForm>

        <ServiceCenterTitle>
          <FormattedMessage
            id='Detail service center'
            defaultMessage='Detail service center'
          />
        </ServiceCenterTitle>

        <InforWrapper>

          <div>
            <TagTitle>
              <FormattedMessage
                id='Nama'
                defaultMessage='Nama'
              />
            </TagTitle>
            <TagContent>
              {
                totalServiceCenterList.length
                  ? decodeURI(totalServiceCenterList.find(({ code }) => code === payload['service_center'])?.name)
                  : payload['service_center']
              }
            </TagContent>
          </div>

          <div>

            <TagTitle>
              <FormattedMessage
                id='Alamat'
                defaultMessage='Alamat'
              />
            </TagTitle>
            <TagContent>
              {branchNameAndAddress}
            </TagContent>

          </div>
        </InforWrapper>
      </ServiceCenterShowForm>

    </ViewServiceCenterFormWrapper>
  )
}

export default connect((state) => ({
  serviceCenterBrandList: state.Claim.serviceCenterBrandList,
  totalServiceCenterList: state.Claim.totalServiceCenterList
}), {
  getServiceCenterBrandList,
  getTotalServiceCenter
})(ViewServiceCenterForm)
