import styled from 'styled-components'

export const CustomCheckBoxContainer = styled.div`

      .ant-checkbox-checked .ant-checkbox-inner{
      background: ${props => props.checkedColor};
      border: 2px solid ${props => props.checkedColor};
      border-radius: 4px;
    }

       .main {
            display: block;
            position: relative;
            padding-left: ${props => props.paddingLeft ? props.paddingLeft : '45px'};
            cursor: pointer;
            font-size: 20px;
            margin: 0px;
        }
          
        /* Hide the default checkbox */
        input[type=checkbox] {
            visibility: hidden;
        }
          
        /* Creating a custom checkbox
        based on demand */
        .geekmark {
            position: absolute;
            top: ${props => props.checkedBoxTopAlignment};
            left:  ${props => props.checkedBoxLeftAllignment};
            height: ${props => props.width};
            width: ${props => props.height};
            background: #FFFFFF;
            border: 2px solid ${props => props.unCheckedBorderColor};
            border-radius: ${props => props.checkedBorderRadius};
        }
          
        /* Specify the background color to be
        shown when checkbox is checked */
        .main input:checked ~ .geekmark {
          background: ${props => props.checkedColor};
          border: 2px solid ${props => props.checkedColor};
          border-radius: 4px;
        }
          
        /* Checkmark to be shown in checkbox */
        /* It is not be shown when not checked */
        .geekmark:after {
            content: "";
            position: absolute;
            display: none;
        }
          
        /* Display checkmark when checked */
        .main input:checked ~ .geekmark:after {
            display: block;
        }
          
        /* Styling the checkmark using webkit */
        /* Rotated the rectangle by 45 degree and 
        showing only two border to make it look
        like a tickmark */
        .main .geekmark:after {
            left:  ${props => `${props.checkedPosition.left || 6}px`};
            bottom: ${props => `${props.checkedPosition.bottom || 5}px`};
            width: ${props => `${props.checkedPosition.width || 8}px`};
            height: ${props => `${props.checkedPosition.height || 16}px`};
            border: 2px solid ${props => props.borderColor};
            border-width: 0 2px 2px 0;
            -webkit-transform: rotate(45deg);
            -ms-transform: rotate(45deg);
            transform: rotate(45deg);

            //    display: block;
        /* height: 13px;
        width: 7px;
        left: 5px;
        bottom: 3px;
        border-radius: 2px; */
        }
`
