const loadImage = (src) =>
  new Promise((resolve) => {
    const img = new Image()
    img.onload = () => {
      if (img.width && img.height) resolve(img)
      else resolve(null)
    }
    img.onerror = () => resolve(null)
    img.src = src
  })

// Backend OCR reads the timestamp off the strip. Tesseract needs roughly a 30px
// cap height to be reliable, which for this stack is a ~42px font.
export const OCR_MIN_FONT_PX = 42
export const MONO_ADVANCE = 0.6
export const MIN_OUTPUT_W = 960
export const MAX_DIM = 2560
export const LOGO_SIZE_RATIO = 0.7

export const MONO_STACK =
  "'DejaVu Sans Mono', 'Roboto Mono', Menlo, Consolas, monospace"

const PAD_EM = 0.6
const GAP_EM = 0.8
const STRIP_EM = 1.8
// Absorbs the sub-pixel rounding of padding, gap and logo width so the text
// still fits when the font lands exactly on OCR_MIN_FONT_PX.
const SLACK_EM = 0.25

/**
 * Everything below is expressed in em of the timestamp font, so the whole strip
 * scales with the image instead of being pinned to absolute pixels.
 */
export const computeStripLayout = ({
  width,
  height,
  textLength,
  logoAspect = 0,
  advance = MONO_ADVANCE,
}) => {
  const logoEm = logoAspect ? logoAspect * LOGO_SIZE_RATIO : 0
  const gapEm = logoAspect ? GAP_EM : 0
  const denom = advance * textLength + PAD_EM * 2 + gapEm + logoEm + SLACK_EM

  // Downscale oversized frames, but never below the width at which the OCR
  // floor still fits on one line -- the timestamp format is fixed by the
  // backend parser, so it cannot be wrapped onto a second line.
  const fit = Math.min(1, MAX_DIM / Math.max(width, height))
  const targetW = Math.max(MIN_OUTPUT_W, Math.ceil(OCR_MIN_FONT_PX * denom))
  const scale = Math.max(fit, targetW / width)

  const outW = Math.round(width * scale)
  const photoH = Math.round(height * scale)
  const fontPx = Math.floor(outW / denom)

  const padX = Math.ceil(fontPx * PAD_EM)
  const gap = Math.ceil(fontPx * gapEm)
  const logoH = Math.floor(fontPx * LOGO_SIZE_RATIO)
  const logoW = Math.ceil(logoH * logoAspect)
  const stripH = Math.round(fontPx * STRIP_EM)
  const textY = photoH + stripH / 2

  return {
    scale,
    outW,
    outH: photoH + stripH,
    photoH,
    stripH,
    fontPx,
    availableW: outW - padX * 2 - gap - logoW,
    textW: advance * textLength * fontPx,
    textX: padX,
    textY,
    logoW,
    logoH,
    logoX: outW - padX - logoW,
    logoY: photoH + (stripH - logoH) / 2,
  }
}

export const applyWatermark = async (imageBlob, timestamp) => {
  const sourceBlobUrl = URL.createObjectURL(imageBlob)
  const sourceImg = await loadImage(sourceBlobUrl)
  if (!sourceImg) {
    URL.revokeObjectURL(sourceBlobUrl)
    throw new Error('Failed to load source image')
  }

  const logoImg = await loadImage(
    `${process.env.PUBLIC_URL || ''}/img/pp-black.png`
  )
  const logoAspect =
    logoImg && logoImg.width && logoImg.height
      ? logoImg.width / logoImg.height
      : 0

  const canvas = document.createElement('canvas')
  const ctx = canvas.getContext('2d')

  // Measure the real advance rather than trusting 0.6em -- feeding the true
  // value into the layout makes the canvas grow to fit a wide font instead of
  // shrinking the text below the OCR floor.
  ctx.font = `bold 100px ${MONO_STACK}`
  const measured = ctx.measureText(timestamp).width
  const advance = measured ? measured / 100 / timestamp.length : MONO_ADVANCE

  const layout = computeStripLayout({
    width: sourceImg.width,
    height: sourceImg.height,
    textLength: timestamp.length,
    logoAspect,
    advance,
  })

  canvas.width = layout.outW
  canvas.height = layout.outH

  ctx.drawImage(sourceImg, 0, 0, layout.outW, layout.photoH)
  URL.revokeObjectURL(sourceBlobUrl)

  ctx.fillStyle = '#FFFFFF'
  ctx.fillRect(0, layout.photoH, layout.outW, layout.stripH)

  if (logoImg) {
    ctx.drawImage(
      logoImg,
      layout.logoX,
      layout.logoY,
      layout.logoW,
      layout.logoH
    )
  }

  ctx.fillStyle = '#000000'
  ctx.textBaseline = 'middle'
  ctx.font = `bold ${layout.fontPx}px ${MONO_STACK}`
  ctx.fillText(timestamp, layout.textX, layout.textY)

  return new Promise((resolve, reject) => {
    canvas.toBlob(
      (blob) => {
        if (blob) resolve(blob)
        else reject(new Error('Canvas toBlob failed'))
      },
      'image/jpeg',
      0.92
    )
  })
}
