/* eslint-disable react/jsx-filename-extension */
import React, { useState } from 'react'
import { FormattedMessage, useIntl } from 'react-intl'
import { get } from 'lodash'

import { Checkbox } from 'antd'
import TextInput from '../Textinput'
import ImageUplaod from '../ImageUpload'
import {
  BOOLEANOPTIONS,
  CHRONOLOGYFIELDITEMS,
  FORMFIELDTYPES,
} from '../../constants/constants'
// import ChronologyBuilder from '../ChronologyBuilder'
import DatePicker from '../DatePickerV2'
import CustomCheckBox from '../CustomCheckBox/CustomCheckBox'
import { COLORS } from '../../constants/colors'
import MultiImageUpload from '../MultiImageUpload'
import {
  BottomBorderContainer,
  DisclaimerContainer,
  DisclaimerLabel,
  ErrorText,
  Label,
  RequiredMark,
} from './dynamicForm.style'
import SelectDropdown from '../SelectV2/selectV2'
import Boolean from '../Boolean'
import Asterisk from '../Asterisk'
import TimePicker from '../TimePickerV2'
import IntlMessages from '../utility/intlMessages'
import { LANG_STRINGS } from '../../constants/lang'
import DisclaimerModal from '../DisclaimerModal'
import CarSketch from '../CarSketch'
import moment from 'moment'

const IMAGE_LIMIT_MBS = 10
const LOWER_LIMIT_MBS = 0.01

const DynamicForm = ({
  language: _language = 'id',
  errors = {},
  values = {},
  onChangeHandler,
  formData,
  onImageUplaodSuccess = () => {},
  // setValidateChronlogyStates,
  validateChronologyStates = {},
  changeErrorStatus,
  formName,
  claimId,
  productKey: _productKey,
  partner: _partner,
  packageName: _packageName,
}) => {
  const intl = useIntl()
  const { formatMessage } = intl
  const uploadFile = (url, name) => {
    onImageUplaodSuccess(url, name)
  }
  const [showDisclaimerModal, setShowDisclaimerModal] = useState(false)

  const renderLabel = (attr) => {
    const { required } = attr
    if (CHRONOLOGYFIELDITEMS.includes(attr.type)) return null
    if (attr.type === FORMFIELDTYPES.DISCLAIMER) return null
    if (attr.type === FORMFIELDTYPES.CHECKBOX) return null
    return (
      <Label>
        {attr.name === 'claim_amount' ? (
          <>
            <IntlMessages id={`${attr.label}`} />{' '}
            <IntlMessages id='(Masukkan jumlah klaim Anda, untuk bagian desimal gunakan koma (,) atau titik (.))' />
          </>
        ) : (
          <IntlMessages id={`${attr.label}`} />
        )}
        {required ? <RequiredMark /> : null}
      </Label>
    )
  }

  const renderFormAttribute = (attr) => {
    const {
      name,
      type,
      label,
      options,
      is_multiple_value_required: isMultipleValueRequired,
      is_editable: isEditabled,
      calendar_date_end_on: endingDate,
      calendar_date_starting_from: startingDate,
      is_only_camera: isOnlyCamera,
    } = attr

    const disabled = !isEditabled
    const placeholder = get(attr, 'user_guideline.placeholder', label)
    const userGuildeLineImage = get(attr, 'user_guideline.imageGuide.value', '')

    switch (type) {
      case FORMFIELDTYPES.choices:
      case FORMFIELDTYPES.CHOICESEXTERNAL: {
        const opList = options.map((item) => ({
          displayName: intl.formatMessage({ id: item[1] || ' ' }),
          value: item[0],
        }))
        return (
          <SelectDropdown
            error={errors[name]}
            disabled={disabled}
            options={opList}
            placeholder={placeholder}
            onSelect={(value) => onChangeHandler({ value, name })}
          />
        )
      }
      case FORMFIELDTYPES.YEAR: {
        const yearOptions = new Array(100)
          .fill(0)
          .map((_, index) => ({
            value: index + 1951,
            displayName: index + 1951,
          }))
          .sort((a, b) => b - a)
        return (
          <SelectDropdown
            value={values[name]}
            error={errors[name]}
            disabled={disabled}
            options={yearOptions}
            placeholder={placeholder}
            onSelect={(value) => onChangeHandler({ value, name })}
          />
        )
      }
      case FORMFIELDTYPES.DATE:
        return (
          <DatePicker
            name={name}
            form={{}}
            value={values[name]}
            disabled={disabled}
            error={errors[name]}
            endingDate={endingDate ? moment.utc(endingDate).tz("Asia/Jakarta").startOf("day") : null}
            startingDate={startingDate ? moment.utc(startingDate).tz("Asia/Jakarta").startOf("day") : null}
            changeErrorStatus={changeErrorStatus}
            handleDateChange={(value) => onChangeHandler({ value, name })}
          />
        )

      case 'time':
        return (
          <TimePicker
            name={name}
            value={values[name]}
            error={errors[name]}
            disabled={disabled}
            handleTimeChange={(value) => onChangeHandler({ value, name })}
          />
        )
      case FORMFIELDTYPES.ASTERISK:
        return (
          <Asterisk
            disabled={disabled}
            placeholder={get(attr, 'user_guideline.placeholder', label)}
            label={<FormattedMessage id={label || ' '} />}
            form={{}}
            name={name}
            error={errors[name]}
            onChange={onChangeHandler}
            value={values[name] || ''}
          />
        )
      case 'image':
        if (isMultipleValueRequired) {
          return (
            <BottomBorderContainer>
              <MultiImageUpload
                disabled={disabled}
                error={errors[name]}
                value={values[name]}
                name={name}
                label={formatMessage({
                  id: label || ' ',
                })}
                formName={formName}
                claimId={claimId}
                onImageUplaodSuccess={(url) => uploadFile(url, name)}
                acceptedTypes={
                  name === 'cardamages_front_back'
                    ? ['image/jpeg', 'image/jpg', 'image/png']
                    : undefined
                }
                uploadImageTypeAndSizeText={
                  <IntlMessages id={LANG_STRINGS.uploadImageTypeAndSizeText} />
                }
                lowerLimitUploadError={
                  <IntlMessages
                    id={LANG_STRINGS.lowerLimitUploadError}
                    values={{
                      lowerlimit: LOWER_LIMIT_MBS,
                      upperLimit: IMAGE_LIMIT_MBS,
                    }}
                  />
                }
                upperLimitUpladError={
                  <IntlMessages
                    id={LANG_STRINGS.upperLimitUpladError}
                    values={{
                      lowerlimit: LOWER_LIMIT_MBS,
                      upperLimit: IMAGE_LIMIT_MBS,
                    }}
                  />
                }
                userGuildeLineImage={userGuildeLineImage}
                userGuidelineText={LANG_STRINGS.userGuidelineText}
                onlyCamera={isOnlyCamera}
              />
            </BottomBorderContainer>
          )
        }
        return (
            <BottomBorderContainer>
            <ImageUplaod
              disabled={disabled}
              error={errors[name]}
              value={values[name]}
              name={name}
              label={formatMessage({
                id: label || ' ',
              })}
              formName={formName}
              claimId={claimId}
              onImageUplaodSuccess={(url) => uploadFile(url, name)}
              acceptedTypes={
                name === 'cardamages_front_back'
                  ? ['image/jpeg', 'image/jpg', 'image/png']
                  : undefined
              }
              uploadImageTypeAndSizeText={
                <IntlMessages id={LANG_STRINGS.uploadImageTypeAndSizeText} />
              }
              lowerLimitUploadError={
                <IntlMessages
                  id={LANG_STRINGS.lowerLimitUploadError}
                  values={{ lowerlimit: LOWER_LIMIT_MBS }}
                />
              }
              upperLimitUpladError={
                <IntlMessages
                  id={LANG_STRINGS.upperLimitUpladError}
                  values={{ upperLimit: IMAGE_LIMIT_MBS }}
                />
              }
              userGuildeLineImage={userGuildeLineImage}
              userGuidelineText={LANG_STRINGS.userGuidelineText}
              onlyCamera={isOnlyCamera}
            />
          </BottomBorderContainer>
        )
      case 'boolean': {
        const boolOptions = BOOLEANOPTIONS.map(
          ({ value, label: optLabel }) => ({
            label: intl.formatMessage({ id: optLabel }),
            value,
          })
        )
        return (
          <Boolean
            disabled={disabled}
            selected={values[name]}
            onChangeHandler={(value) => onChangeHandler({ name, value })}
            options={boolOptions}
          />
        )
      }
      case 'checkbox':
      case 'disclaimer':
        if (name === 'disclaimer_aus' || name === 'disclaimer' || name === 'agency-mv-tlo-disclaimer-aus' || name === 'disclaimer_aus_tlo') {
          return (
            <div
              style={{
                display: 'flex',
                alignItems: 'flex-start',
                marginTop: '10px',
                gap: '6px',
                flexWrap: 'wrap',
              }}
            >
              <Checkbox
                onChange={(e) => {
                  const value = e.target.checked
                  onChangeHandler({ name, value })
                }}
                checked={values[name]}
                disabled={disabled}
              />
              <span style={{ fontSize: 13, lineHeight: '18px' }}>
                <IntlMessages
                id={LANG_STRINGS.disclaimerText}
                values={{
                  highlight: (chunks) => (
                    <span
                      onClick={() => setShowDisclaimerModal(true)}
                      style={{
                        textDecoration: 'underline',
                        cursor: 'pointer',
                      }}
                    >
                      {chunks}
                    </span>
                  ),
                }}
              />
              </span>
              <DisclaimerModal
                isOpen={showDisclaimerModal}
                onClose={() => setShowDisclaimerModal(false)}
              />
            </div>
          )
        }
        return (
          <DisclaimerContainer>
            <CustomCheckBox
              onChange={(e) => {
                const value = e.target.checked
                onChangeHandler({ name, value })
              }}
              width='20px'
              height='20px'
              checkedPosition={{
                height: 14,
                width: 8,
                left: 4,
                bottom: 3,
                borderRadius: 2,
              }}
              checked={values[name]}
              disabled={disabled}
              paddingLeft='12px'
              checkedBoxTopAlignment='5px'
              unCheckedBorderColor={COLORS.monoChromeGrey}
              borderColor={COLORS.white}
              checkedColor={COLORS.tapPartnerBlue}
            />
            <DisclaimerLabel>
              <IntlMessages id={label} />
            </DisclaimerLabel>
          </DisclaimerContainer>
        )
      case 'string':
        switch (name) {
          case 'claim_amount':
            return (
              <TextInput
                disabled={disabled}
                placeholder={get(attr, 'user_guideline.placeholder', label)}
                label={intl.formatMessage({
                  id: label,
                })}
                form={{}}
                name={name}
                error={errors[name]}
                onChange={onChangeHandler}
                value={values[name] || ''}
                type='number'
                inputMode='numeric'
                pattern='[0-9]*'
              />
            )
          case 'nik_number': {
            // NIK-specific validation function
            const validateNIK = (value) => {
              if (!value) return ''
              // General validation for 16 characters
              if (value && value.length !== 16) {
                return 'Invalid NIK (NIK harus berisi 16 karakter)'
              }
              return '' // No error
            }
            const error = validateNIK(values[name])
            // do not mutate the errors prop; pass local error to the input
            return (
              <TextInput
                disabled={disabled}
                placeholder={get(attr, 'user_guideline.placeholder', label)}
                label={intl.formatMessage({
                  id: label,
                })}
                form={{}}
                name={name}
                error={error}
                onChange={onChangeHandler}
                value={values[name] || ''}
                type='number'
                inputMode='numeric'
                pattern='[0-9]*'
              />
            )
          }
          default:
            return (
              <TextInput
                disabled={disabled}
                placeholder={get(attr, 'user_guideline.placeholder', label)}
                label={intl.formatMessage({
                  id: label,
                })}
                form={{}}
                name={name}
                error={errors[name]}
                onChange={onChangeHandler}
                value={values[name] || ''}
              />
            )
        }
      case 'sketch':
        return (
          <CarSketch
            disabled={disabled}
            claim_id={claimId}
            onImageGenerated={(url) => uploadFile(url, name)}
            name={name}
            formName={formName}
            value={values[name]}
          />
        )
      default:
        return (
          <TextInput
            disabled={disabled}
            placeholder={get(attr, 'user_guideline.placeholder', label)}
            label={intl.formatMessage({
              id: label,
            })}
            form={{}}
            name={name}
            error={errors[name]}
            onChange={onChangeHandler}
            value={values[name] || ''}
          />
        )
    }
  }

  const renderErrorText = ({ name }) => {
    if (
      validateChronologyStates[name] &&
      validateChronologyStates[name].chrnologyInputPattern ===
        'usingTemplateBuilder'
    )
      return null
    return (
      <ErrorText>
        <IntlMessages id={errors[name]} />
      </ErrorText>
    )
  }

  return formData.map((attr) => (
    <BottomBorderContainer type={attr.type} key={attr.name}>
      {renderLabel(attr)}
      {renderFormAttribute(attr)}
      {renderErrorText(attr)}
    </BottomBorderContainer>
  ))
}

export default DynamicForm
