import React, { useEffect, useState, useCallback } from 'react'
import { useIntl } from 'react-intl'
import { applyWatermark } from '../../helpers/imageWatermark'
import { compressImage } from '../../helpers/imageCompress'
import { toWatermarkString, toApiFields } from '../../helpers/captureTimestamp'
import { LANG_STRINGS } from '../../constants/lang'
import {
  Fullscreen,
  CameraContainer,
  TopBar,
  CloseBtn,
  VideoContainer,
  Viewfinder,
  Video,
  BottomBar,
  GalleryInfo,
  GalleryThumbs,
  GalleryThumb,
  GalleryCount,
  ShutterBtn,
  Spacer,
  ErrorOverlay,
  ErrorIcon,
  ErrorText,
  ErrorRetryBtn,
  PhotoListOverlay,
  PhotoListContent,
  PhotoListHeader,
  PhotoListTitle,
  PhotoListClose,
  PhotoGrid,
  PhotoGridItem,
  PhotoDeleteBtn,
  PreviewOverlay,
  PreviewImg,
  PreviewActions,
  RetakeBtn,
  UsePhotoBtn,
  BackBtn,
  SwitchCameraBtn,
  DoneBtn,
  ProcessingOverlay,
  ProcessingSpinner,
} from './cameraCapture.style'
import { useCameraCapture } from './useCameraCapture'

const CAMERA_VIEW = 'camera'
const PREVIEW_VIEW = 'preview'

function CameraCapture({ multiple, onCapture, onClose }) {
  const intl = useIntl()
  const {
    videoRef,
    capturedPhotos,
    facingMode,
    startCamera,
    capture,
    addPhoto,
    removePhoto,
    switchCamera,
    reset,
  } = useCameraCapture({ multiple })

  const [cameraError, setCameraError] = useState(null)
  const [processingId, setProcessingId] = useState(null)
  const [showPhotoList, setShowPhotoList] = useState(false)
  const [activeView, setActiveView] = useState(CAMERA_VIEW)
  const [previewPhoto, setPreviewPhoto] = useState(null)

  useEffect(() => {
    startCamera('environment').catch((err) => {
      if (err.name === 'CameraPermissionBlocked') {
        setCameraError('blocked')
      } else {
        setCameraError('denied')
      }
    })
    return () => {
      reset()
    }
  }, []) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    const handleBack = (e) => {
      if (e.key === 'Escape' || e.key === 'Backspace') {
        if (showPhotoList) {
          setShowPhotoList(false)
          return
        }
        if (activeView === PREVIEW_VIEW) {
          setActiveView(CAMERA_VIEW)
          return
        }
        onClose()
      }
    }
    window.addEventListener('keydown', handleBack)
    return () => window.removeEventListener('keydown', handleBack)
  }, [showPhotoList, activeView, onClose])

  const processAndAddPhoto = useCallback(
    async (rawFile) => {
      const rawDate = new Date()
      const watermarkStr = toWatermarkString(rawDate)
      const apiFields = toApiFields(rawDate)
      try {
        const compressed = await compressImage(rawFile)
        const watermarkedBlob = await applyWatermark(compressed, watermarkStr)
        const finalFile = new File([watermarkedBlob], rawFile.name, {
          type: 'image/jpeg',
        })
        return addPhoto(finalFile, apiFields)
      } catch (err) {
        console.warn('Watermark failed, uploading raw:', err)
        return addPhoto(rawFile, apiFields)
      }
    },
    [addPhoto],
  )

  const handleCapture = useCallback(async () => {
    const rawFile = await capture()
    if (!rawFile) return

    setProcessingId(Date.now())
    const photo = await processAndAddPhoto(rawFile)
    setProcessingId(null)

    if (photo) {
      setPreviewPhoto(photo)
      setActiveView(PREVIEW_VIEW)
    }
  }, [capture, processAndAddPhoto])

  const handleUpload = useCallback(() => {
    if (capturedPhotos.length === 0) return
    if (multiple) {
      onCapture(capturedPhotos.map((p) => ({ file: p.file, timestamp: p.captureTimestamp })))
    } else {
      const p = capturedPhotos[0]
      onCapture({ file: p.file, timestamp: p.captureTimestamp })
    }
  }, [multiple, capturedPhotos, onCapture])

  const handleTakeMore = useCallback(() => {
    setActiveView(CAMERA_VIEW)
    setPreviewPhoto(null)
  }, [])

  const handleRetake = useCallback(() => {
    if (previewPhoto) {
      removePhoto(previewPhoto.id)
    }
    setPreviewPhoto(null)
    setActiveView(CAMERA_VIEW)
  }, [previewPhoto, removePhoto])

  const handleBackFromPreview = useCallback(() => {
    setActiveView(CAMERA_VIEW)
    setPreviewPhoto(null)
  }, [])

  const handleDeleteFromList = useCallback(
    (id) => {
      removePhoto(id)
      // +1 after remove means next length is current - 1
      if (capturedPhotos.length - 1 <= 1 && activeView !== CAMERA_VIEW) {
        setActiveView(CAMERA_VIEW)
        setPreviewPhoto(null)
      }
    },
    [removePhoto, capturedPhotos.length, activeView],
  )

  const handleSwitchCamera = useCallback(() => {
    switchCamera().catch((err) => {
      if (err.name === 'CameraPermissionBlocked') {
        setCameraError('blocked')
      } else {
        setCameraError('denied')
      }
    })
  }, [switchCamera])

  return (
    <Fullscreen>
      {/* Camera view — always mounted */}
      <CameraContainer
        style={{
          display: activeView === CAMERA_VIEW ? 'flex' : 'none',
        }}
      >
        <TopBar>
          <CloseBtn onClick={onClose}>✕</CloseBtn>
          <SwitchCameraBtn onClick={handleSwitchCamera}>
            <svg width='20' height='20' viewBox='0 0 24 24' fill='none'>
              <path d='M16 3H8l-2 3H2v14h20V6h-4l-2-3z' stroke='#fff' strokeWidth='1.5' strokeLinecap='round' strokeLinejoin='round'/>
              <circle cx='12' cy='13' r='4' stroke='#fff' strokeWidth='1.5'/>
              <path d='M17 8l2-2m0 0l2 2m-2-2v4' stroke='#fff' strokeWidth='1.5' strokeLinecap='round' strokeLinejoin='round'/>
            </svg>
          </SwitchCameraBtn>
        </TopBar>

        <VideoContainer>
          <Viewfinder>
            <Video ref={videoRef} autoPlay playsInline muted />

            {cameraError && (
              <ErrorOverlay>
                <ErrorIcon>📷</ErrorIcon>
                <ErrorText>
                  {cameraError === 'blocked'
                    ? intl.formatMessage({ id: LANG_STRINGS.cameraPermissionBlocked })
                    : intl.formatMessage({ id: LANG_STRINGS.cameraPermissionDenied })}
                </ErrorText>
                {cameraError === 'blocked' && (
                  <ErrorText
                    style={{ fontSize: 13, opacity: 0.8, marginBottom: 8 }}
                  >
                    {intl.formatMessage({
                      id: LANG_STRINGS.cameraPermissionBlockedGuide,
                    })}
                  </ErrorText>
                )}
                <ErrorRetryBtn onClick={() => window.location.reload()}>
                  {intl.formatMessage({ id: LANG_STRINGS.cameraPermissionRetry })}
                </ErrorRetryBtn>
              </ErrorOverlay>
            )}

            {!!processingId && (
              <ProcessingOverlay>
                <ProcessingSpinner />
              </ProcessingOverlay>
            )}

          </Viewfinder>
        </VideoContainer>

        {!cameraError && (
          <BottomBar>
            {multiple && capturedPhotos.length > 0 ? (
              <GalleryInfo onClick={() => setShowPhotoList(true)}>
                <GalleryThumbs>
                  {capturedPhotos.slice(0, 3).map((p) => (
                    <GalleryThumb key={p.id}>
                      <img src={p.url} alt='' />
                    </GalleryThumb>
                  ))}
                </GalleryThumbs>
                <GalleryCount>{capturedPhotos.length} photos</GalleryCount>
              </GalleryInfo>
            ) : (
              <Spacer />
            )}

            <ShutterBtn
              disabled={!!processingId}
              onClick={handleCapture}
            />

            {multiple && capturedPhotos.length > 0 ? (
              <DoneBtn onClick={handleUpload}>Upload</DoneBtn>
            ) : (
              <Spacer />
            )}
          </BottomBar>
        )}
      </CameraContainer>

      {/* Preview overlay */}
      {activeView === PREVIEW_VIEW && previewPhoto && (
        <PreviewOverlay>
          <TopBar>
            <BackBtn onClick={handleBackFromPreview}>←</BackBtn>
          </TopBar>
          <PreviewImg src={previewPhoto.url} alt='captured' />
          <PreviewActions>
            {multiple ? (
              <>
                <RetakeBtn onClick={handleTakeMore}>Take More</RetakeBtn>
                <UsePhotoBtn onClick={handleUpload}>Upload All</UsePhotoBtn>
              </>
            ) : (
              <>
                <RetakeBtn onClick={handleRetake}>Retake</RetakeBtn>
                <UsePhotoBtn onClick={handleUpload}>Upload</UsePhotoBtn>
              </>
            )}
          </PreviewActions>
        </PreviewOverlay>
      )}

      {/* Photo list overlay */}
      {showPhotoList && (
        <PhotoListOverlay>
          <PhotoListContent>
            <PhotoListHeader>
              <PhotoListTitle>Photos ({capturedPhotos.length})</PhotoListTitle>
              <PhotoListClose onClick={() => setShowPhotoList(false)}>
                ✕
              </PhotoListClose>
            </PhotoListHeader>
            <PhotoGrid>
              {capturedPhotos.map((p) => (
                <PhotoGridItem key={p.id}>
                  <img src={p.url} alt='' />
                  <PhotoDeleteBtn onClick={() => handleDeleteFromList(p.id)}>
                    ×
                  </PhotoDeleteBtn>
                </PhotoGridItem>
              ))}
            </PhotoGrid>
          </PhotoListContent>
        </PhotoListOverlay>
      )}
    </Fullscreen>
  )
}

export default CameraCapture
